// frontend/src/admin/components/AdminNotificationCenter.jsx
// ============================================================
//  🔔 AdminNotificationCenter — زنگوله اعلان‌های ادمین
//  ✅ FIX v3:
//    - لینک‌های ?section=... (هماهنگ با AdminApp)
//    - fallback برای لینک‌های pathname قدیمی
//    - حفظ یک export default
// ============================================================

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from '../axiosConfig';
import { toFaRaw } from '../../utils/numbers';
import { SiteImage } from '../../utils/SiteImage';

const POLL_INTERVAL_MS = 30000;
const MAX_DROPDOWN_ITEMS = 10;
const FEED_LIMIT = 100;
const STORAGE_KEY = 'adminNotificationsLastSeen';

// ===== Config per event type =====
const EVENT_CONFIG = {
  new_order: { icon: '🆕', iconKey: 'icon_new', label: 'سفارش جدید', color: 'brand' },
  new_receipt: { icon: '💳', iconKey: 'icon_payment', label: 'فیش جدید', color: 'accent' },
  cancelled_order: { icon: '❌', iconKey: 'icon_error', label: 'لغو سفارش', color: 'rose' },
  new_ticket: { icon: '🎫', iconKey: 'icon_ticket', label: 'تیکت جدید', color: 'brand' },
  user_reply: { icon: '💬', iconKey: 'icon_chat', label: 'پاسخ کاربر', color: 'ink' },
  new_testimonial: { icon: '⭐', iconKey: 'icon_star', label: 'نظر جدید', color: 'accent' },
};

const COLOR_CLASSES = {
  brand: {
    iconBg:
      'bg-brand-100 dark:bg-brand-500/20 text-brand-700 dark:text-brand-300',
    border: 'border-brand-200 dark:border-brand-500/30',
    dot: 'bg-brand-500',
    highlight: 'bg-brand-50/50 dark:bg-brand-500/5',
  },
  accent: {
    iconBg:
      'bg-accent-100 dark:bg-accent-500/20 text-accent-700 dark:text-accent-300',
    border: 'border-accent-200 dark:border-accent-500/30',
    dot: 'bg-accent-500',
    highlight: 'bg-accent-50/50 dark:bg-accent-500/5',
  },
  rose: {
    iconBg:
      'bg-rose-100 dark:bg-rose-500/20 text-rose-700 dark:text-rose-300',
    border: 'border-rose-200 dark:border-rose-500/30',
    dot: 'bg-rose-500',
    highlight: 'bg-rose-50/50 dark:bg-rose-500/5',
  },
  ink: {
    iconBg: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200',
    border: 'border-ink-200 dark:border-dark-600',
    dot: 'bg-ink-500',
    highlight: 'bg-ink-100/50 dark:bg-ink-700/30',
  },
};

// ===== safeDate — با افزودن Z برای تاریخ‌های UTC بدون timezone =====
function safeDate(iso) {
  if (!iso) return null;
  let s = String(iso);
  if (!s.includes('Z') && !/[+-]\d{2}:?\d{2}$/.test(s)) {
    s = s + 'Z';
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function toFaTimeAgo(iso) {
  const d = safeDate(iso);
  if (!d) return '—';
  const diff = Date.now() - d.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'همین الان';
  if (mins < 60) return `${toFaRaw(mins)} دقیقه پیش`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${toFaRaw(hours)} ساعت پیش`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${toFaRaw(days)} روز پیش`;
  return new Intl.DateTimeFormat('fa-IR', {
    month: 'short',
    day: 'numeric',
  }).format(d);
}

// ===== خواندن/نوشتن lastSeen =====
function readLastSeen() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const d = new Date(raw);
    return isNaN(d.getTime()) ? null : d;
  } catch {
    return null;
  }
}

function writeLastSeen(date) {
  try {
    localStorage.setItem(STORAGE_KEY, date.toISOString());
  } catch {
    /* silent */
  }
}

// ============================================================
//  ✅ NEW: normalizeLink
//  لینک‌های backend اکنون ?section=... هستند، اما برای سازگاری
//  با لینک‌های قدیمی، pathname را به query تبدیل می‌کند.
// ============================================================
function normalizeLink(link) {
  if (!link) return '';
  if (link.includes('section=')) return link;
  if (link === '/admin/notifications') return '/admin?section=notifications';
  if (link === '/admin/payments') return '/admin?section=payments';
  if (link === '/admin/tickets') return '/admin?section=tickets';
  if (link === '/admin/users') return '/admin?section=users';
  if (link === '/admin/orders') return '/admin?section=orders';
  if (link === '/admin') return '/admin?section=dashboard';
  const orderMatch = link.match(/^\/admin\/orders\/(\d+)$/);
  if (orderMatch) {
    return `/admin?section=order-detail&orderId=${orderMatch[1]}`;
  }
  return link;
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function AdminNotificationCenter({ onUnreadChange }) {
  const navigate = useNavigate();

  const [open, setOpen] = useState(false);
  const [events, setEvents] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isMobile, setIsMobile] = useState(
    () => typeof window !== 'undefined' && window.innerWidth < 640
  );

  const containerRef = useRef(null);
  const panelRef = useRef(null);
  const isMountedRef = useRef(true);
  const lastSeenRef = useRef(readLastSeen());

  // ===== Resize =====
  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 640);
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  // ===== محاسبهٔ unread =====
  const computeUnread = useCallback((evts) => {
    const lastSeen = lastSeenRef.current;
    if (!lastSeen) {
      return evts.length;
    }
    let count = 0;
    for (const e of evts) {
      const d = safeDate(e.created_at);
      if (d && d > lastSeen) count++;
    }
    return count;
  }, []);

  // ===== Fetch =====
  const fetchFeed = useCallback(
    async (silent = false) => {
      if (!silent) setLoading(true);
      try {
        const res = await axios.get('/admin/notifications/feed', {
          params: { limit: FEED_LIMIT },
        });
        if (!isMountedRef.current) return;

        const list = res.data?.events || [];

        // اولین بار: اگه هیچ lastSeen نداریم، به «یک ساعت پیش» ست کن
        if (lastSeenRef.current === null) {
          const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
          lastSeenRef.current = oneHourAgo;
          writeLastSeen(oneHourAgo);
        }

        setEvents(list);
        const unread = computeUnread(list);
        setUnreadCount(unread);
        if (onUnreadChange) onUnreadChange(unread);
      } catch (err) {
        if (err.response?.status === 401) {
          /* ignore */
        }
      } finally {
        if (isMountedRef.current) setLoading(false);
      }
    },
    [computeUnread, onUnreadChange]
  );

  // ===== Initial + polling =====
  useEffect(() => {
    isMountedRef.current = true;
    fetchFeed(true);

    const id = setInterval(() => {
      if (isMountedRef.current && document.visibilityState === 'visible') {
        fetchFeed(true);
      }
    }, POLL_INTERVAL_MS);

    const onVisible = () => {
      if (document.visibilityState === 'visible') fetchFeed(true);
    };
    document.addEventListener('visibilitychange', onVisible);

    return () => {
      isMountedRef.current = false;
      clearInterval(id);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [fetchFeed]);

  // ===== Click outside =====
  useEffect(() => {
    if (!open) return;
    const handler = (e) => {
      if (isMobile) return;
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target) &&
        panelRef.current &&
        !panelRef.current.contains(e.target)
      ) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    document.addEventListener('touchstart', handler);
    return () => {
      document.removeEventListener('mousedown', handler);
      document.removeEventListener('touchstart', handler);
    };
  }, [open, isMobile]);

  // ===== Escape =====
  useEffect(() => {
    if (!open) return;
    const handler = (e) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [open]);

  // ===== Body lock (mobile) =====
  useEffect(() => {
    if (!open || !isMobile) return;
    const prev = document.body.style.overflow;
    const prevPadding = document.body.style.paddingRight;
    const sw = window.innerWidth - document.documentElement.clientWidth;
    document.body.style.overflow = 'hidden';
    if (sw > 0) document.body.style.paddingRight = `${sw}px`;
    return () => {
      document.body.style.overflow = prev || '';
      document.body.style.paddingRight = prevPadding || '';
    };
  }, [open, isMobile]);

  // ===== Mark all seen =====
  const handleMarkAllSeen = () => {
    const now = new Date();
    lastSeenRef.current = now;
    writeLastSeen(now);
    setUnreadCount(0);
    if (onUnreadChange) onUnreadChange(0);
  };

  // ===== Click event =====
  const handleClick = (event) => {
    setOpen(false);
    const target = normalizeLink(event.link);
    if (target) {
      navigate(target);
    }
  };

  // ===== تشخیص unread per item =====
  const isUnread = useCallback((event) => {
    const lastSeen = lastSeenRef.current;
    if (!lastSeen) return true;
    const d = safeDate(event.created_at);
    return d ? d > lastSeen : false;
  }, []);

  const displayList = events.slice(0, MAX_DROPDOWN_ITEMS);
  const badgeText = unreadCount > 99 ? '۹۹+' : toFaRaw(unreadCount);

  return (
    <div className="relative" ref={containerRef}>
      {/* ===== Bell ===== */}
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className={`relative w-10 h-10 flex items-center justify-center rounded-xl transition touch-target ${
          open
            ? 'text-brand-600 dark:text-brand-400 bg-brand-50 dark:bg-brand-500/15'
            : 'text-ink-600 dark:text-cream-300 hover:text-brand-600 dark:hover:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-500/15'
        }`}
        aria-label={`اعلان‌ها${
          unreadCount > 0 ? `، ${toFaRaw(unreadCount)} مورد جدید` : ''
        }`}
        aria-expanded={open}
        aria-haspopup="dialog"
        title="اعلان‌ها"
      >
        <svg
          className="w-5 h-5"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
        >
          <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9" />
          <path d="M13.73 21a2 2 0 0 1-3.46 0" />
        </svg>
        {unreadCount > 0 && (
          <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] px-1 rounded-full bg-rose-500 text-white text-[10px] font-black flex items-center justify-center shadow-sm animate-pulse font-num">
            {badgeText}
          </span>
        )}
      </button>

      {/* ===== Panel ===== */}
      {open && (
        <>
          {isMobile && (
            <div
              className="fixed inset-0 bg-ink-900/50 backdrop-blur-sm z-[60]"
              onClick={() => setOpen(false)}
              aria-hidden="true"
            />
          )}

          <div
            ref={panelRef}
            role="dialog"
            aria-modal={isMobile ? 'true' : undefined}
            aria-label="لیست اعلان‌های ادمین"
            className={
              isMobile
                ? 'fixed top-0 left-0 right-0 z-[61] max-h-[85vh] bg-paper-50 dark:bg-ink-800 rounded-b-3xl shadow-editorial overflow-hidden flex flex-col animate-slide-down'
                : 'absolute left-0 mt-2 w-[400px] max-w-[calc(100vw-2rem)] bg-paper-50 dark:bg-ink-800 rounded-2xl shadow-editorial overflow-hidden flex flex-col z-50 border border-ink-200 dark:border-dark-700 animate-slide-down'
            }
            style={
              isMobile
                ? { paddingTop: 'env(safe-area-inset-top, 0px)' }
                : undefined
            }
          >
            {isMobile && (
              <div className="w-12 h-1.5 bg-ink-300 dark:bg-dark-600 rounded-full mx-auto mt-2" />
            )}

            {/* Header */}
            <div className="flex items-center justify-between gap-2 px-4 py-3 border-b border-ink-200 dark:border-dark-700 flex-shrink-0">
              <div className="flex items-center gap-2 min-w-0">
                <h3 className="text-sm font-black text-ink-900 dark:text-cream-100">
                  اعلان‌های سیستم
                </h3>
                {unreadCount > 0 && (
                  <span className="inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full bg-rose-500 text-white text-[10px] font-black font-num">
                    {badgeText}
                  </span>
                )}
              </div>
              <div className="flex items-center gap-1">
                {unreadCount > 0 && (
                  <button
                    type="button"
                    onClick={handleMarkAllSeen}
                    className="text-[11px] font-black text-brand-600 dark:text-brand-400 hover:text-brand-800 dark:hover:text-brand-300 px-2.5 py-1.5 rounded-lg hover:bg-brand-50 dark:hover:bg-brand-500/15 active:bg-brand-100 transition touch-target"
                    title="همه را دیده‌ام"
                  >
                    ✓ همه
                  </button>
                )}
                {isMobile && (
                  <button
                    type="button"
                    onClick={() => setOpen(false)}
                    className="w-9 h-9 flex items-center justify-center rounded-lg text-ink-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/15 transition touch-target"
                    aria-label="بستن"
                  >
                    ✕
                  </button>
                )}
              </div>
            </div>

            {/* List */}
            <div className="flex-1 overflow-y-auto overscroll-contain">
              {loading && events.length === 0 ? (
                <div className="p-10 text-center">
                  <div className="inline-block w-6 h-6 border-2 border-brand-500 border-t-transparent rounded-full animate-spin mb-2" />
                  <div className="text-xs text-ink-500 dark:text-cream-400 font-bold">
                    در حال بارگذاری...
                  </div>
                </div>
              ) : displayList.length === 0 ? (
                <div className="p-10 text-center">
                  <div className="text-5xl mb-3 opacity-50" aria-hidden="true">
                    🔔
                  </div>
                  <div className="text-sm text-ink-600 dark:text-cream-300 font-black mb-1">
                    هیچ اعلان جدیدی نیست
                  </div>
                  <div className="text-xs text-ink-400 dark:text-cream-500">
                    وقتی رویداد جدیدی رخ بده، اینجا نمایش داده می‌شه
                  </div>
                </div>
              ) : (
                <ul className="divide-y divide-ink-100 dark:divide-dark-700">
                  {displayList.map((ev) => {
                    const cfg =
                      EVENT_CONFIG[ev.type] || EVENT_CONFIG.new_order;
                    const cls = COLOR_CLASSES[cfg.color] || COLOR_CLASSES.ink;
                    const unread = isUnread(ev);
                    const icon = ev.icon || cfg.icon;

                    return (
                      <li key={ev.key}>
                        <button
                          type="button"
                          onClick={() => handleClick(ev)}
                          className={`w-full text-right flex items-start gap-3 p-3 hover:bg-paper-100 dark:hover:bg-ink-700/50 active:bg-paper-200 dark:active:bg-ink-700 transition ${
                            unread ? cls.highlight : ''
                          }`}
                        >
                          <div
                            className={`w-9 h-9 rounded-xl flex items-center justify-center text-base flex-shrink-0 border ${cls.border} ${cls.iconBg}`}
                            aria-hidden="true"
                          >
                            {icon}
                          </div>

                          <div className="flex-1 min-w-0">
                            <div className="flex items-start gap-1.5 mb-0.5">
                              <span className="text-xs font-black text-ink-900 dark:text-cream-100 leading-tight flex-1 min-w-0 break-safe">
                                {ev.title}
                              </span>
                              {unread && (
                                <span
                                  className={`w-1.5 h-1.5 rounded-full flex-shrink-0 mt-1.5 ${cls.dot}`}
                                  aria-label="جدید"
                                />
                              )}
                            </div>
                            {ev.message && (
                              <div className="text-[11px] text-ink-600 dark:text-cream-300 leading-relaxed line-clamp-2 mt-0.5">
                                {ev.message}
                              </div>
                            )}
                            <div className="flex items-center gap-2 mt-1 text-[10px] text-ink-400 dark:text-cream-500">
                              <span className="font-num">
                                {toFaTimeAgo(ev.created_at)}
                              </span>
                              {ev.priority === 'high' && (
                                <>
                                  <span aria-hidden="true">·</span>
                                  <span className="text-rose-600 dark:text-rose-400 font-black">
                                    فوری
                                  </span>
                                </>
                              )}
                            </div>
                          </div>
                        </button>
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>

            {/* Footer */}
            <div className="border-t border-ink-200 dark:border-dark-700 p-2 flex-shrink-0">
              <button
                type="button"
                onClick={() => {
                  setOpen(false);
                  navigate('/admin?section=notifications');
                }}
                className="w-full min-h-[44px] flex items-center justify-center gap-1.5 text-xs font-black text-brand-600 dark:text-brand-400 hover:bg-brand-50 dark:hover:bg-brand-500/15 active:bg-brand-100 rounded-xl transition touch-target"
              >
                <span>مشاهدهٔ همهٔ اعلان‌ها</span>
                <SiteImage imageKey="icon_arrow_left" fallback="←" alt="" className="leading-none inline-flex" />
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
}