// frontend/src/user/userAxios.js
// ============================================================
//  ✅ FIX v3:
//  - API_BASE از config/api.js (منبع واحد)
//  - حذف readEnv محلی و import.meta
//  - export API_BASE برای سازگاری با importهای قبلی
//  - timeout 30s
//  - 401: فقط از /panel/* redirect، حفظ sessionStorage pending
//  - 403: پیام کاربرپسند
//  - Network error: پیام فارسی
//  - guard برای config.headers
// ============================================================
import axios from 'axios';
import { API_BASE } from '../config/api';

// برای سازگاری با فایل‌هایی که قبلاً API_BASE را از اینجا import می‌کردند
export { API_BASE };

// ============================================================
//  مسیرهای محافظت‌شده — فقط از اینجا 401 redirect می‌شود
// ============================================================
const isProtectedPath = (pathname) =>
  typeof pathname === 'string' && pathname.startsWith('/panel');

// ============================================================
//  در 401 فقط توکن/دیتای کاربر پاک می‌شود
//  کلیدهای pendingOrder / pendingDog / quickCalc* حفظ می‌شوند
//  تا کاربر بعد از login بتواند سفارشش را کامل کند
// ============================================================
function clearAuthStorage() {
  try {
    localStorage.removeItem('userToken');
    localStorage.removeItem('userData');
    // ⚠️ عمداً این‌ها پاک نمی‌شوند:
    //   sessionStorage.pendingOrder
    //   sessionStorage.pendingDog
    //   sessionStorage.quickCalcForm
    //   sessionStorage.quickCalcResult
  } catch {
    /* localStorage unavailable */
  }
}

// ============================================================
//  redirect با حفظ موقعیت
// ============================================================
function buildLoginRedirect(pathname) {
  if (pathname.includes('/payment')) {
    return '/login?next=order';
  }
  return '/login';
}

// ============================================================
//  Axios instance
// ============================================================
const userAxios = axios.create({
  baseURL: API_BASE,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// ============================================================
//  Request interceptor — افزودن توکن کاربر
// ============================================================
userAxios.interceptors.request.use(
  (config) => {
    try {
      const token = localStorage.getItem('userToken');
      if (token) {
        if (!config.headers) {
          config.headers = {};
        }
        config.headers.Authorization = `Bearer ${token}`;
      }
    } catch {
      /* localStorage unavailable */
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// ============================================================
//  Response interceptor
// ============================================================
userAxios.interceptors.response.use(
  (response) => response,
  (error) => {
    const status = error.response?.status;

    // ────────────────────────────────────────────
    //  401 — نشست منقضی شده
    // ────────────────────────────────────────────
    if (status === 401) {
      clearAuthStorage();

      const { pathname } = window.location;

      if (isProtectedPath(pathname) && !pathname.startsWith('/login')) {
        const redirectUrl = buildLoginRedirect(pathname);
        if (window.location.pathname !== redirectUrl.split('?')[0]) {
          window.location.href = redirectUrl;
        }
      }
    }

    // ────────────────────────────────────────────
    //  403 — دسترسی غیرمجاز
    // ────────────────────────────────────────────
    if (status === 403) {
      if (!error.response.data) {
        error.response.data = {};
      }
      if (!error.response.data.detail) {
        error.response.data.detail = 'دسترسی به این بخش مجاز نیست.';
      }
    }

    // ────────────────────────────────────────────
    //  422 — خطاهای اعتبارسنجی (flatten)
    // ────────────────────────────────────────────
    if (status === 422) {
      const detail = error.response?.data?.detail;
      if (Array.isArray(detail)) {
        error.response.data.detail = detail
          .map((e) => e?.msg || JSON.stringify(e))
          .join(' - ');
      } else if (detail && typeof detail === 'object') {
        error.response.data.detail = JSON.stringify(detail);
      }
    }

    // ────────────────────────────────────────────
    //  Network error / timeout → پیام فارسی
    // ────────────────────────────────────────────
    if (!error.response) {
      if (error.code === 'ECONNABORTED' || error.message?.includes('timeout')) {
        error.userMessage =
          'زمان درخواست به پایان رسید. لطفاً اتصال اینترنت را بررسی کنید و دوباره تلاش کنید.';
      } else if (error.message === 'Network Error' || error.code === 'ERR_NETWORK') {
        error.userMessage =
          'خطا در اتصال به سرور. لطفاً اتصال اینترنت را بررسی کنید.';
      } else {
        error.userMessage = 'خطای نامشخص در ارتباط با سرور.';
      }
    }

    return Promise.reject(error);
  }
);

export default userAxios;