// frontend/src/user/hooks/useCart.js
// ============================================================
// 🛒 سبد خرید کاربر — localStorage + CustomEvent
// ✅ v5:
//   - استفاده از constants/storageKeys برای کلیدها و رویداد
//   - schema version روی هر آیتم (برای مهاجرت‌های آینده)
//   - خواندن آیتم‌های قدیمی (بدون version) برای سازگاری عقب‌رو
//   - بقیهٔ منطق v4 بدون تغییر
// ============================================================

import { useState, useEffect, useCallback } from 'react';
import {
  CART_STORAGE_KEY,
  CART_UPDATED_EVENT,
  CART_SCHEMA_VERSION,
} from '../../constants/storageKeys';

const CART_KEY = CART_STORAGE_KEY;
const CART_EVENT = CART_UPDATED_EVENT;
export const MAX_CART_ITEMS = 10;

// ============================================================
//  helpers
// ============================================================
function readCart() {
  try {
    const raw = localStorage.getItem(CART_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];

    // اعتبارسنجی پایه + مهاجرت سبک: نسخهٔ فعلی را روی آیتم‌های قدیمی می‌گذاریم
    return parsed
      .filter(
        (x) => x && typeof x === 'object' && x.localId && x.formPayload
      )
      .map((x) => ({
        ...x,
        schemaVersion: x.schemaVersion || 0, // 0 = پیش از این نسخه
      }));
  } catch {
    return [];
  }
}

function writeCart(items) {
  try {
    localStorage.setItem(CART_KEY, JSON.stringify(items));
    window.dispatchEvent(new CustomEvent(CART_EVENT));
    return true;
  } catch (err) {
    if (process.env.NODE_ENV !== 'production') {
      console.warn('[useCart] write failed:', err);
    }
    return false;
  }
}

function makeLocalId() {
  return `ci_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function pickNumber(...values) {
  for (const v of values) {
    if (v == null || v === '') continue;
    const n = Number(v);
    if (!Number.isNaN(n)) return n;
  }
  return 0;
}

function normalizeFormPayload(form) {
  if (!form || typeof form !== 'object') return {};
  return {
    dog_id: form.dog_id ?? null,
    dog_name: String(form.dog_name || '').trim(),
    weight_kg: Number(form.weight_kg) || 0,
    age_months: Number(form.age_months) || 0,
    breed: form.breed || 'medium',
    temperature: form.temperature || 'moderate',
    is_neutered: !!form.is_neutered,
    activity: form.activity || 'moderate',
    bcs: form.bcs || 'ideal',
    pregnancy: form.pregnancy || 'no',
    disease: form.disease || 'healthy',
    stress: form.stress || 'low',
    surgery: form.surgery || 'no_surgery',
    allergy_type: form.allergy_type || 'none',
    allergy_details: form.allergy_details || '',
    allergens: Array.isArray(form.allergens) ? form.allergens : [],
    days_count: Number(form.days_count) || 7,
    phone: form.phone || '',
    email: form.email || '',
  };
}

function buildSummarySnapshot(summary, normalizedForm, originalForm) {
  const dogName =
    (originalForm?.dog_name || summary?.dog_name || '')
      .toString()
      .trim() || 'سگ';

  return {
    dog_name: dogName,
    total_price: pickNumber(
      summary?.pricing?.total_order_price,
      summary?.order_total?.total_price_toman,
      originalForm?.total_price,
      originalForm?.total_order_price,
      originalForm?.total_price_toman
    ),
    daily_price: pickNumber(
      summary?.pricing?.final_price_daily,
      summary?.daily?.price_toman,
      originalForm?.daily_price,
      originalForm?.final_price_daily
    ),
    days_count:
      summary?.order_total?.days ??
      (Number(normalizedForm?.days_count) || 7),
    total_weight_kg: pickNumber(
      summary?.order_total?.total_weight_kg,
      originalForm?.total_weight_kg
    ),
    weight_kg:
      Number(normalizedForm?.weight_kg) ||
      pickNumber(summary?.weight_kg) ||
      0,
  };
}

// ============================================================
//  core — shared by hook.addItem & addPendingOrderToCart
// ============================================================
function buildCartItem(form, summary) {
  const normalizedForm = normalizeFormPayload(form);
  const snapshot = buildSummarySnapshot(summary, normalizedForm, form);
  return {
    localId: makeLocalId(),
    dogId: normalizedForm.dog_id ?? null,
    dogName: snapshot.dog_name,
    formPayload: normalizedForm,
    summary: snapshot,
    addedAt: Date.now(),
    schemaVersion: CART_SCHEMA_VERSION,
  };
}

function performAddItem(form, summary) {
  const current = readCart();

  if (current.length >= MAX_CART_ITEMS) {
    return { ok: false, reason: 'limit', max: MAX_CART_ITEMS };
  }

  const normalizedForm = normalizeFormPayload(form);

  if (normalizedForm.dog_id) {
    const duplicate = current.find(
      (x) =>
        x.formPayload?.dog_id === normalizedForm.dog_id &&
        Number(x.formPayload?.days_count) ===
          Number(normalizedForm.days_count)
    );
    if (duplicate) {
      return {
        ok: false,
        reason: 'duplicate',
        message: 'این سگ با همین مدت قبلاً در سبد هست.',
      };
    }
  }

  const item = buildCartItem(form, summary);
  const next = [...current, item];
  const written = writeCart(next);

  if (!written) {
    return { ok: false, reason: 'storage', message: 'ذخیره سبد ناموفق بود.' };
  }

  return { ok: true, item };
}

// ============================================================
//  addPendingOrderToCart — تابع مستقل
// ============================================================
export function addPendingOrderToCart(pendingOrder) {
  if (!pendingOrder || typeof pendingOrder !== 'object') {
    return { ok: false, reason: 'invalid', message: 'سفارش نامعتبر است.' };
  }

  const form =
    pendingOrder.form ||
    pendingOrder.formPayload ||
    pendingOrder.orderForm ||
    pendingOrder;

  const summary =
    pendingOrder.summary ||
    pendingOrder.result ||
    pendingOrder.calcResult ||
    pendingOrder.calculation ||
    pendingOrder.orderResult ||
    {};

  return performAddItem(form, summary);
}

// ============================================================
//  hook
// ============================================================
export function useCart() {
  const [items, setItems] = useState(() => readCart());

  useEffect(() => {
    const sync = () => setItems(readCart());
    window.addEventListener('storage', sync);
    window.addEventListener(CART_EVENT, sync);
    return () => {
      window.removeEventListener('storage', sync);
      window.removeEventListener(CART_EVENT, sync);
    };
  }, []);

  const addItem = useCallback(({ form, summary } = {}) => {
    return performAddItem(form, summary);
  }, []);

  const removeItem = useCallback((localId) => {
    const current = readCart();
    const next = current.filter((x) => x.localId !== localId);
    writeCart(next);
    return { ok: next.length < current.length };
  }, []);

  const clearCart = useCallback(() => {
    try {
      localStorage.removeItem(CART_KEY);
    } catch {
      /* ignore */
    }
    window.dispatchEvent(new CustomEvent(CART_EVENT));
  }, []);

  const hasItem = useCallback(
    (dogId, daysCount) => {
      if (!dogId) return false;
      return items.some(
        (x) =>
          x.formPayload?.dog_id === dogId &&
          Number(x.formPayload?.days_count) === Number(daysCount)
      );
    },
    [items]
  );

  const totalCount = items.length;
  const totalAmount = items.reduce(
    (sum, x) => sum + (Number(x.summary?.total_price) || 0),
    0
  );

  return {
    items,
    addItem,
    removeItem,
    clearCart,
    hasItem,
    totalCount,
    totalAmount,
    MAX_ITEMS: MAX_CART_ITEMS,
  };
}

export function clearCartStorage() {
  try {
    localStorage.removeItem(CART_KEY);
  } catch {
    /* ignore */
  }
  window.dispatchEvent(new CustomEvent(CART_EVENT));
}