// frontend/src/user/components/Testimonials.jsx
// ============================================================
//  🐾 Testimonials v4 — Miko Warm Palette
//  - Featured Quote: گرادیانت آجری ← کدویی
//  - ستاره‌ها: طلایی میکو
//  - Badge تأیید: زیتونی
//  - دکمه‌های CTA: آجری ← کدویی
//  - پس‌زمینه: کرم گرم + هاله‌های کاروت/اولیو
// ============================================================

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Link } from 'react-router-dom';
import publicAxios from '../publicAxios';
import { toFa } from '../../utils/numbers';
import { SiteImage } from '../../utils/SiteImage';
import { resolveAssetUrl } from '../../config/api';
import {
  STORAGE_KEYS,
  AUTH_EVENT,
  USER_DATA_EVENT,
} from '../../constants/storageKeys';

// ============================================================
//  🎯 CTA destination
// ============================================================
const GUEST_CTA = '/register';
const AUTH_CTA = '/panel/testimonials/new';

// ============================================================
//  🎬 Hook: prefers-reduced-motion
// ============================================================
function usePrefersReducedMotion() {
  const [prefersReduced, setPrefersReduced] = useState(false);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const handler = () => setPrefersReduced(mq.matches);
    handler();
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, []);

  return prefersReduced;
}

// ============================================================
//  ⭐ Stars — طلایی میکو
// ============================================================
function Stars({ count = 5, size = 'md' }) {
  const sizeCls =
    {
      sm: 'text-sm',
      md: 'text-base',
      lg: 'text-xl',
    }[size] || 'text-base';

  return (
    <div
      className={`flex items-center gap-0.5 ${sizeCls}`}
      aria-label={`${toFa(count)} از ۵ ستاره`}
      role="img"
    >
      {Array.from({ length: 5 }).map((_, i) => (
        <span
          key={i}
          className={
            i < count
              ? 'text-miko-gold'
              : 'text-miko-dark/20 dark:text-dark-600'
          }
          aria-hidden="true"
        >
          ★
        </span>
      ))}
    </div>
  );
}

// ============================================================
//  🏅 VerifiedBadge — زیتونی میکو
// ============================================================
function VerifiedBadge({ size = 'md' }) {
  const sz =
    size === 'sm'
      ? 'text-[9px] px-1.5 py-0.5 gap-1'
      : 'text-[10px] px-2 py-0.5 gap-1.5';

  return (
    <span
      className={`inline-flex items-center rounded-full bg-miko-olive/10 dark:bg-miko-olive/20 text-miko-olive dark:text-miko-leaf border border-miko-olive/30 dark:border-miko-olive/40 font-black whitespace-nowrap ${sz}`}
    >
      <span className="inline-flex items-center justify-center w-3 h-3 rounded-full bg-miko-olive text-white p-[2px] font-black flex-shrink-0">
        <SiteImage
          imageKey="icon_check"
          fallback="✓"
          alt=""
          className="w-full h-full object-contain"
        />
      </span>
      <span>تأیید شده</span>
    </span>
  );
}

// ============================================================
//  🌟 Featured Quote — گرادیانت آجری ← کدویی
// ============================================================
function FeaturedQuote({ testimonial, prefersReduced }) {
  const [imgError, setImgError] = useState(false);

  const fullUrl = resolveAssetUrl(testimonial.avatar_url);
  const initial = (testimonial.owner_name || '?').charAt(0).toUpperCase();

  return (
    <div className="relative bg-gradient-to-br from-miko-rust to-miko-pumpkin text-white rounded-3xl overflow-hidden shadow-miko-lg">

      <div
        className="absolute -top-40 -right-40 w-96 h-96 rounded-full bg-white/10 blur-3xl pointer-events-none"
        aria-hidden="true"
      />
      <div
        className="absolute -bottom-40 -left-40 w-96 h-96 rounded-full bg-miko-gold/20 blur-3xl pointer-events-none"
        aria-hidden="true"
      />

      <div
        className="absolute top-0 right-1/2 translate-x-1/2 w-20 h-0.5 bg-miko-carrot/70"
        aria-hidden="true"
      />

      <div
        className="absolute top-4 right-6 sm:top-6 sm:right-10 font-display text-[8rem] sm:text-[14rem] md:text-[18rem] leading-none text-white/15 select-none pointer-events-none"
        aria-hidden="true"
      >
        ”
      </div>

      <div className="relative p-5 sm:p-10 md:p-14 lg:p-16">

        <div className="flex items-center justify-between gap-3 sm:gap-4 mb-5 sm:mb-8 flex-wrap">
          <div className="flex items-center gap-3 min-w-0">
            <div className="w-10 h-px bg-miko-carrot/80 flex-shrink-0" aria-hidden="true" />
            <span className="text-[10px] sm:text-[11px] font-black tracking-[0.2em] uppercase text-white/90">
              از زبان یک مشتری واقعی
            </span>
          </div>

          <VerifiedBadge />
        </div>

        <blockquote className="font-display font-black text-white text-xl sm:text-2xl md:text-3xl lg:text-4xl leading-[1.35] tracking-tight mb-6 sm:mb-10 max-w-4xl">
          «{testimonial.quote}»
        </blockquote>

        <div className="flex items-center gap-4 sm:gap-5 flex-wrap">

          <div className="relative flex-shrink-0">
            <div className="w-14 h-14 sm:w-20 sm:h-20 rounded-full overflow-hidden ring-4 ring-white/40 border-2 border-white">
              {fullUrl && !imgError ? (
                <img
                  src={fullUrl}
                  alt={testimonial.owner_name}
                  loading="lazy"
                  className="w-full h-full object-cover"
                  onError={() => setImgError(true)}
                />
              ) : (
                <div className="w-full h-full bg-miko-cream flex items-center justify-center text-miko-rust text-xl sm:text-2xl font-black">
                  {initial}
                </div>
              )}
            </div>
            <div className="absolute -bottom-1 -left-1 bg-miko-cream text-miko-rust rounded-full w-7 h-7 sm:w-8 sm:h-8 flex items-center justify-center border-2 border-white shadow-md p-1 sm:p-1.5">
              <SiteImage
                imageKey="icon_dog"
                fallback="🐕"
                alt=""
                className="w-full h-full object-contain"
              />
            </div>
          </div>

          <div className="flex-1 min-w-0">
            <div className="font-display font-black text-white text-base sm:text-lg leading-tight break-words">
              {testimonial.owner_name}
            </div>
            <div className="text-xs sm:text-sm text-white/85 mt-1.5 flex items-center gap-2 flex-wrap">
              <span>صاحب {testimonial.dog_name}</span>
              {testimonial.dog_breed && (
                <>
                  <span className="text-white/40" aria-hidden="true">
                    ·
                  </span>
                  <span className="text-white/90">{testimonial.dog_breed}</span>
                </>
              )}
              {testimonial.city && (
                <>
                  <span className="text-white/40" aria-hidden="true">
                    ·
                  </span>
                  <span className="text-white/85 inline-flex items-center gap-1">
                    <SiteImage
                      imageKey="icon_location"
                      fallback="📍"
                      alt=""
                      className="w-3 h-3 object-contain flex-shrink-0"
                    />
                    <span>{testimonial.city}</span>
                  </span>
                </>
              )}
            </div>
          </div>

          <div className="ml-auto sm:ml-0 flex-shrink-0">
            <Stars count={testimonial.rating} size="lg" />
          </div>
        </div>
      </div>
    </div>
  );
}

// ============================================================
//  💬 Quote Card — کرم گرم + بورد کاروت
// ============================================================
function QuoteCard({ testimonial, prefersReduced }) {
  const [imgError, setImgError] = useState(false);

  const fullUrl = resolveAssetUrl(testimonial.avatar_url);
  const initial = (testimonial.owner_name || '?').charAt(0).toUpperCase();

  return (
    <article
      className={`group relative bg-miko-cream dark:bg-ink-800 rounded-3xl border border-miko-carrot/25 dark:border-dark-700 p-5 sm:p-6 hover:border-miko-carrot dark:hover:border-miko-rust/40 transition-all duration-300 flex flex-col overflow-hidden ${
        prefersReduced ? '' : 'hover:shadow-lifted hover:-translate-y-1'
      }`}
    >
      <div
        className="absolute top-0 right-1/2 translate-x-1/2 w-12 h-0.5 bg-miko-carrot/60"
        aria-hidden="true"
      />

      <div className="flex items-start justify-between gap-3 mb-3">
        <div
          className="font-display text-5xl leading-none text-miko-rust/30 select-none"
          aria-hidden="true"
        >
          ”
        </div>
        <VerifiedBadge size="sm" />
      </div>

      <blockquote className="text-miko-dark dark:text-cream-100 text-sm sm:text-base leading-relaxed flex-1 mb-5 break-words">
        {testimonial.quote}
      </blockquote>

      <div className="mb-4">
        <Stars count={testimonial.rating} size="sm" />
      </div>

      <div className="flex items-center gap-3 pt-4 border-t border-miko-carrot/20 dark:border-dark-700">
        <div
          className={`w-11 h-11 rounded-full overflow-hidden flex-shrink-0 ring-2 ring-miko-carrot/40 dark:ring-miko-carrot/30 transition-all ${
            prefersReduced
              ? ''
              : 'group-hover:ring-miko-rust dark:group-hover:ring-miko-carrot/70'
          }`}
        >
          {fullUrl && !imgError ? (
            <img
              src={fullUrl}
              alt={testimonial.owner_name}
              loading="lazy"
              className={`w-full h-full object-cover transition-transform duration-500 ${
                prefersReduced ? '' : 'group-hover:scale-110 group-hover:rotate-3'
              }`}
              onError={() => setImgError(true)}
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-miko-rust to-miko-pumpkin flex items-center justify-center text-white text-sm font-black">
              {initial}
            </div>
          )}
        </div>

        <div className="min-w-0 flex-1">
          <div className="font-bold text-miko-dark dark:text-cream-100 text-xs sm:text-sm leading-tight truncate">
            {testimonial.owner_name}
          </div>
          <div className="text-[10px] sm:text-[11px] text-miko-dark/60 dark:text-cream-400 mt-1 flex items-center gap-1.5 flex-wrap">
            <span className="truncate inline-flex items-center gap-1">
              <SiteImage
                imageKey="icon_dog"
                fallback="🐕"
                alt=""
                className="w-3 h-3 object-contain flex-shrink-0"
              />
              <span>{testimonial.dog_name}</span>
            </span>
            {testimonial.city && (
              <>
                <span
                  className="text-miko-dark/30 dark:text-dark-600"
                  aria-hidden="true"
                >
                  ·
                </span>
                <span className="truncate">{testimonial.city}</span>
              </>
            )}
          </div>
        </div>
      </div>
    </article>
  );
}

// ============================================================
//  📝 Skeleton Loading
// ============================================================
function TestimonialsSkeleton() {
  return (
    <div className="space-y-4" role="status" aria-label="در حال بارگذاری نظرات">
      <span className="sr-only">در حال بارگذاری نظرات مشتریان</span>

      <div className="bg-miko-carrot/10 dark:bg-ink-800 rounded-3xl p-6 sm:p-12 h-72 animate-pulse">
        <div className="h-3 w-32 bg-miko-carrot/20 dark:bg-ink-700 rounded mb-6" />
        <div className="space-y-3 mb-8">
          <div className="h-6 w-full bg-miko-carrot/20 dark:bg-ink-700 rounded" />
          <div className="h-6 w-4/5 bg-miko-carrot/20 dark:bg-ink-700 rounded" />
        </div>
        <div className="flex items-center gap-3">
          <div className="w-16 h-16 rounded-full bg-miko-carrot/20 dark:bg-ink-700" />
          <div className="flex-1 space-y-2">
            <div className="h-4 w-32 bg-miko-carrot/20 dark:bg-ink-700 rounded" />
            <div className="h-3 w-48 bg-miko-carrot/20 dark:bg-ink-700 rounded" />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 sm:gap-5">
        {[1, 2].map((i) => (
          <div
            key={i}
            className="bg-miko-cream dark:bg-ink-800 rounded-3xl border border-miko-carrot/20 dark:border-dark-700 p-5 sm:p-6 h-56 animate-pulse"
          >
            <div className="h-8 w-8 bg-miko-carrot/20 dark:bg-ink-700 rounded mb-4" />
            <div className="space-y-3 mb-6">
              <div className="h-3 w-full bg-miko-carrot/20 dark:bg-ink-700 rounded" />
              <div className="h-3 w-4/5 bg-miko-carrot/20 dark:bg-ink-700 rounded" />
            </div>
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 rounded-full bg-miko-carrot/20 dark:bg-ink-700" />
              <div className="h-4 w-24 bg-miko-carrot/20 dark:bg-ink-700 rounded" />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ============================================================
//  🎯 کامپوننت اصلی
// ============================================================
export default function Testimonials() {
  const [testimonials, setTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({ total: 0, average: 0 });
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  const prefersReduced = usePrefersReducedMotion();

  useEffect(() => {
    const syncAuth = () => {
      try {
        setIsLoggedIn(!!localStorage.getItem(STORAGE_KEYS.USER_TOKEN));
      } catch {
        setIsLoggedIn(false);
      }
    };

    syncAuth();
    window.addEventListener('storage', syncAuth);
    window.addEventListener(AUTH_EVENT, syncAuth);
    window.addEventListener(USER_DATA_EVENT, syncAuth);

    return () => {
      window.removeEventListener('storage', syncAuth);
      window.removeEventListener(AUTH_EVENT, syncAuth);
      window.removeEventListener(USER_DATA_EVENT, syncAuth);
    };
  }, []);

  const fetchTestimonials = useCallback(async () => {
    setLoading(true);
    try {
      const [listRes, statsRes] = await Promise.all([
        publicAxios.get('/api/testimonials', {
          params: { limit: 12 },
        }),
        publicAxios.get('/api/testimonials/stats'),
      ]);

      const list = listRes.data?.testimonials || [];
      const statsData = statsRes.data || {};

      setTestimonials(list);

      setStats({
        total: statsData.total_approved || 0,
        average: statsData.average_rating || 0,
      });
    } catch (err) {
      if (process.env.NODE_ENV !== 'production') {
        console.error('خطا در دریافت نظرات:', err);
      }
      setTestimonials([]);
      setStats({ total: 0, average: 0 });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTestimonials();
  }, [fetchTestimonials]);

  const { featured, others } = useMemo(() => {
    if (testimonials.length === 0) {
      return { featured: null, others: [] };
    }
    const feat = testimonials.find((t) => t.is_featured) || testimonials[0];
    const rest = testimonials.filter((t) => t.id !== feat?.id);
    return { featured: feat, others: rest };
  }, [testimonials]);

  const hasAnyTestimonial = testimonials.length > 0;
  const showStats = hasAnyTestimonial && stats.total > 0;

  const displayAverage =
    showStats && stats.average > 0 ? stats.average.toFixed(1) : null;

  const scrollToCalculator = () => {
    const el = document.getElementById('quick-calculator');
    if (!el) return;
    const HEADER_OFFSET = 80;
    const top =
      el.getBoundingClientRect().top + window.pageYOffset - HEADER_OFFSET;
    window.scrollTo({
      top,
      behavior: prefersReduced ? 'auto' : 'smooth',
    });
  };

  const ctaTo = isLoggedIn ? AUTH_CTA : GUEST_CTA;

  return (
    <section
      id="testimonials"
      className="relative py-12 sm:py-16 md:py-24 bg-miko-cream/60 dark:bg-ink-950 overflow-hidden"
      aria-labelledby="testimonials-title"
    >
      <div
        className="absolute -top-40 -left-40 w-96 h-96 rounded-full bg-miko-carrot/25 dark:bg-miko-carrot/8 blur-3xl pointer-events-none"
        aria-hidden="true"
      />
      <div
        className="absolute bottom-0 right-0 w-80 h-80 rounded-full bg-miko-olive/20 dark:bg-miko-leaf/8 blur-3xl pointer-events-none"
        aria-hidden="true"
      />

      <div className="relative max-w-editorial mx-auto px-4 sm:px-8 lg:px-12">

        <div className="flex flex-col md:flex-row md:items-end md:justify-between gap-5 sm:gap-6 mb-10 sm:mb-12 md:mb-16">
          <div className="max-w-2xl min-w-0">
            <div className="flex items-center gap-3 mb-5 sm:mb-6">
              <div className="w-12 h-px bg-miko-rust flex-shrink-0" aria-hidden="true" />
              <span className="text-[11px] font-black tracking-[0.2em] uppercase text-miko-rust dark:text-miko-carrot">
                از زبان مشتری‌ها
              </span>
            </div>

            <h2
              id="testimonials-title"
              className="font-display font-black text-miko-dark dark:text-cream-100 text-3xl sm:text-5xl md:text-6xl lg:text-7xl leading-[1] sm:leading-[0.95] tracking-tightest break-words"
            >
              سگ‌های{' '}
              <span className="relative inline-block">
                <span className="relative z-10 text-miko-rust dark:text-miko-carrot">خوشحال</span>
                <span
                  className="absolute bottom-1 right-0 left-0 h-2 sm:h-3 md:h-4 bg-miko-carrot/40 dark:bg-miko-carrot/30 -z-0"
                  aria-hidden="true"
                />
              </span>
              ،
              <br />
              صاحبان راضی.
            </h2>
          </div>

          {showStats && (
            <div className="flex-shrink-0 flex md:flex-col gap-4 md:gap-3 items-start md:items-end text-left md:text-right">
              <div>
                <div className="font-display font-black text-2xl sm:text-4xl md:text-5xl text-miko-rust dark:text-miko-carrot font-num leading-none">
                  {toFa(stats.total)}
                </div>
                <div className="text-[10px] sm:text-[11px] text-miko-dark/60 dark:text-cream-400 mt-1 font-black">
                  نظر تأییدشده
                </div>
              </div>

              {displayAverage && (
                <>
                  <div className="hidden md:block w-24 h-px bg-miko-carrot/30 dark:bg-dark-700" />
                  <div>
                    <div className="font-display font-black text-2xl sm:text-4xl md:text-5xl text-miko-rust dark:text-miko-carrot font-num leading-none">
                      {toFa(displayAverage)}
                      <span className="text-lg sm:text-xl text-miko-dark/40 dark:text-cream-500">
                        /۵
                      </span>
                    </div>
                    <div className="text-[10px] sm:text-[11px] text-miko-dark/60 dark:text-cream-400 mt-1 font-black">
                      میانگین امتیاز
                    </div>
                  </div>
                </>
              )}
            </div>
          )}
        </div>

        {loading ? (
          <TestimonialsSkeleton />
        ) : testimonials.length === 0 ? (
          <div className="bg-miko-cream dark:bg-ink-900 rounded-3xl border-2 border-dashed border-miko-carrot/30 dark:border-dark-700 p-8 sm:p-16 text-center">
            <div
              className="inline-flex items-center justify-center w-16 h-16 sm:w-20 sm:h-20 rounded-3xl bg-miko-carrot/10 dark:bg-miko-carrot/15 border border-miko-carrot/30 dark:border-miko-rust/30 mb-5 p-4 sm:p-5"
              aria-hidden="true"
            >
              <SiteImage
                imageKey="icon_chat"
                fallback="💬"
                alt=""
                className="w-full h-full object-contain opacity-90"
              />
            </div>

            <h3 className="font-display font-black text-miko-dark dark:text-cream-100 text-lg sm:text-xl mb-3">
              هنوز نظری ثبت نشده
            </h3>

            <p className="text-sm text-miko-dark/65 dark:text-cream-400 leading-relaxed max-w-md mx-auto mb-6">
              اینجا فقط نظرات واقعی مشتریان بعد از تأیید ادمین نمایش داده می‌شه.
              اولین نفری باش که تجربه‌اش رو با ما به اشتراک می‌ذاره.
            </p>

            <Link
              to={ctaTo}
              className={`group inline-flex items-center justify-center gap-2 min-h-[52px] px-7 py-3.5 bg-gradient-to-br from-miko-rust to-miko-pumpkin hover:opacity-95 active:opacity-90 text-white rounded-2xl text-sm font-black shadow-miko hover:shadow-miko-lg transition-all touch-target ${
                prefersReduced
                  ? ''
                  : 'hover:-translate-y-0.5 active:translate-y-0'
              }`}
            >
              <SiteImage
                imageKey="icon_edit"
                fallback="✍️"
                alt=""
                className="w-4 h-4 object-contain"
              />
              <span>{isLoggedIn ? 'ثبت اولین نظر' : 'ثبت‌نام و ثبت نظر'}</span>
              <span
                className="group-hover:-translate-x-1 transition-transform"
                aria-hidden="true"
              >
                ←
              </span>
            </Link>
          </div>
        ) : (
          <>
            {featured && (
              <div className="mb-6 sm:mb-8 md:mb-10">
                <FeaturedQuote
                  testimonial={featured}
                  prefersReduced={prefersReduced}
                />
              </div>
            )}

            {others.length > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-5 md:gap-6">
                {others.map((t) => (
                  <QuoteCard
                    key={t.id}
                    testimonial={t}
                    prefersReduced={prefersReduced}
                  />
                ))}
              </div>
            )}
          </>
        )}

        <div className="mt-10 sm:mt-14 md:mt-20 flex flex-col items-center text-center gap-5 sm:gap-6">
          <div className="max-w-xl">
            <h3 className="font-display font-black text-miko-dark dark:text-cream-100 text-xl sm:text-3xl leading-tight tracking-tight mb-3">
              سگت هم لایق غذای اختصاصیه.
            </h3>
            <p className="text-sm sm:text-base text-miko-dark/65 dark:text-cream-400 leading-relaxed">
              {isLoggedIn
                ? 'تجربه‌ات رو با ما به اشتراک بذار — نظرت به صاحبان پت‌های دیگه کمک می‌کنه.'
                : 'به جمع خانوادهٔ ما بپیوند — محاسبه رایگانه.'}
            </p>
          </div>

          <div className="flex flex-col sm:flex-row gap-3 w-full sm:w-auto justify-center">
            <Link
              to={ctaTo}
              className={`group inline-flex items-center justify-center gap-2 min-h-[52px] sm:min-h-[56px] px-6 sm:px-8 py-3.5 sm:py-4 bg-gradient-to-br from-miko-rust to-miko-pumpkin hover:opacity-95 active:opacity-90 text-white rounded-2xl text-sm font-black shadow-miko hover:shadow-miko-lg transition-all touch-target ${
                prefersReduced
                  ? ''
                  : 'hover:-translate-y-0.5 active:translate-y-0'
              }`}
            >
              {isLoggedIn ? (
                <>
                  <SiteImage
                    imageKey="icon_edit"
                    fallback="✍️"
                    alt=""
                    className="w-4 h-4 object-contain flex-shrink-0"
                  />
                  <span>ثبت نظر من</span>
                </>
              ) : (
                <>
                  <SiteImage
                    imageKey="icon_sparkles"
                    fallback="🚀"
                    alt=""
                    className="w-4 h-4 object-contain flex-shrink-0"
                  />
                  <span>ثبت‌نام و شروع</span>
                  <span
                    className="group-hover:-translate-x-1 transition-transform"
                    aria-hidden="true"
                  >
                    ←
                  </span>
                </>
              )}
            </Link>

            <button
              type="button"
              onClick={scrollToCalculator}
              className={`group inline-flex items-center justify-center gap-2 min-h-[52px] sm:min-h-[56px] px-5 sm:px-6 py-3.5 sm:py-4 bg-miko-cream dark:bg-ink-800 hover:bg-miko-carrot/15 dark:hover:bg-ink-700 text-miko-dark dark:text-cream-100 border-2 border-miko-carrot/30 dark:border-dark-700 rounded-2xl text-sm font-black transition-all touch-target ${
                prefersReduced
                  ? ''
                  : 'hover:-translate-y-0.5 active:translate-y-0'
              }`}
            >
              <SiteImage
                imageKey="icon_paw"
                fallback="🐾"
                alt=""
                className="w-4 h-4 object-contain flex-shrink-0"
              />
              <span>مشاهدهٔ رژیم</span>
              <span
                className="group-hover:-translate-x-1 transition-transform"
                aria-hidden="true"
              >
                ←
              </span>
            </button>
          </div>

          <div className="text-[11px] text-miko-dark/50 dark:text-cream-500 flex items-center gap-1.5 flex-wrap justify-center">
            <SiteImage
              imageKey="icon_lock"
              fallback="🔒"
              alt=""
              className="w-3.5 h-3.5 object-contain"
            />
            <span>بدون تعهد، بدون نیاز به کارت بانکی</span>
          </div>
        </div>
      </div>
    </section>
  );
}