// frontend/src/admin/components/MiniChart.jsx
import React, { useState, useMemo, useRef, useCallback } from 'react';

// ============================================================
//  ابزارهای کمکی
// ============================================================
const fmt = (n) => Math.round(n || 0).toLocaleString('fa-IR');

const fmtShort = (n) => {
  const num = Math.round(n || 0);
  if (num >= 1_000_000_000) return `${(num / 1_000_000_000).toFixed(1)}م`;
  if (num >= 1_000_000) return `${(num / 1_000_000).toFixed(1)} میلیون`;
  if (num >= 1_000) return `${(num / 1_000).toFixed(0)} هزار`;
  return num.toLocaleString('fa-IR');
};

// تبدیل عدد به فرمت تاریخ شمسی کوتاه
const toPersianDateShort = (isoDate) => {
  if (!isoDate) return '';
  try {
    const d = new Date(isoDate);
    return d.toLocaleDateString('fa-IR', { month: 'short', day: 'numeric' });
  } catch {
    return '';
  }
};

// روز هفته
const toPersianWeekday = (isoDate) => {
  if (!isoDate) return '';
  try {
    const d = new Date(isoDate);
    return d.toLocaleDateString('fa-IR', { weekday: 'short' });
  } catch {
    return '';
  }
};

// ============================================================
//  🎨 Editorial constants
// ============================================================
const CHART_COLORS = {
  brand: '#AF6B24',      // رنگ پیش‌فرض
  accent: '#2E7D32',
  ink: '#6B664F',
  rose: '#E11D48',
  grid: '#E8E0D0',       // paper-300
  gridDark: '#3D3B30',   // dark-700
  axisLabel: '#A8A29E',  // ink-300
  axisLabelDark: '#6B664F', // cream-500
  barText: '#78716C',    // ink-400
  barTextDark: '#A8A29E', // cream-300
  dot: '#FDFCFA',        // paper-50
  tooltipBg: '#0C0A09',  // ink-900
  tooltipBgDark: '#060503', // ink-950
};

// تشخیص دیوایس لمسی
const isTouchDevice = () => {
  if (typeof window === 'undefined') return false;
  return 'ontouchstart' in window || navigator.maxTouchPoints > 0;
};

// تبدیل clientX به ایندکس نقطه
function getClientXIndex(clientX, container, itemsCount) {
  if (!container || itemsCount === 0) return null;
  const rect = container.getBoundingClientRect();
  if (rect.width === 0) return null;
  const xRatio = (clientX - rect.left) / rect.width;
  const idx = Math.round(xRatio * (itemsCount - 1));
  return Math.max(0, Math.min(itemsCount - 1, idx));
}

// محاسبه موقعیت tooltip (با clamping)
function getTooltipLeft(pointX, totalWidth, minPct = 12, maxPct = 88) {
  const pct = (pointX / totalWidth) * 100;
  return Math.max(minPct, Math.min(maxPct, pct));
}

// ============================================================
//  LineChart — نمودار خطی با tooltip و پرش
//
//  Props:
//    - data: آرایه‌ای از { label, value } یا { date, revenue }
//    - valueKey: کلید مقدار در هر آیتم (پیش‌فرض 'value')
//    - labelKey: کلید برچسب در هر آیتم (پیش‌فرض 'label')
//    - color: رنگ خط ('brand' | 'accent' | 'ink' | hex)
//    - height: ارتفاع نمودار روی دسکتاپ (پیش‌فرض 220)
//    - mobileHeight: ارتفاع نمودار روی موبایل (پیش‌فرض 180)
//    - showArea: نمایش پرشدن زیر نمودار
//    - showDots: نمایش نقطه‌ها
//    - showGrid: نمایش خطوط افقی
//    - formatValue: تابع فرمت مقدار برای tooltip
// ============================================================
export function LineChart({
  data = [],
  valueKey = 'value',
  labelKey = 'label',
  color = CHART_COLORS.brand, // 🎨 brand-500 (کاراملی)
  height = 220,
  mobileHeight = 180,
  showArea = true,
  showDots = true,
  showGrid = true,
  formatValue = fmt,
  className = '',
}) {
  const [hoveredIdx, setHoveredIdx] = useState(null);
  const containerRef = useRef(null);

  // ✅ MOBILE: ارتفاع بر اساس عرض صفحه
  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== 'undefined' ? window.innerWidth < 640 : false
  );

  React.useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 640);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  const chartHeight = isMobile ? mobileHeight : height;

  // ابعاد داخلی SVG
  const padding = isMobile
    ? { top: 16, right: 8, bottom: 26, left: 8 }
    : { top: 20, right: 12, bottom: 32, left: 12 };
  const width = 600;
  const innerW = width - padding.left - padding.right;
  const innerH = chartHeight - padding.top - padding.bottom;

  // محاسبات داده
  const values = useMemo(() => data.map(d => Number(d[valueKey]) || 0), [data, valueKey]);
  const maxValue = Math.max(...values, 1);
  const minValue = 0;
  const range = maxValue - minValue || 1;

  // محاسبه نقاط
  const points = useMemo(() => {
    if (data.length === 0) return [];
    if (data.length === 1) {
      return [{
        x: padding.left + innerW / 2,
        y: padding.top + innerH / 2,
        value: values[0],
        item: data[0],
        idx: 0,
      }];
    }
    const stepX = innerW / (data.length - 1);
    return data.map((item, idx) => {
      const value = Number(item[valueKey]) || 0;
      const ratio = (value - minValue) / range;
      return {
        x: padding.left + idx * stepX,
        y: padding.top + innerH - ratio * innerH,
        value,
        item,
        idx,
      };
    });
  }, [data, valueKey, innerW, innerH, range, values, padding.left, padding.top]);

  // مسیر خطی
  const linePath = useMemo(() => {
    if (points.length === 0) return '';
    if (points.length === 1) return `M ${points[0].x} ${points[0].y}`;

    let path = `M ${points[0].x} ${points[0].y}`;
    for (let i = 1; i < points.length; i++) {
      const prev = points[i - 1];
      const curr = points[i];
      const cp1x = prev.x + (curr.x - prev.x) / 3;
      const cp2x = prev.x + (curr.x - prev.x) * 2 / 3;
      path += ` C ${cp1x} ${prev.y}, ${cp2x} ${curr.y}, ${curr.x} ${curr.y}`;
    }
    return path;
  }, [points]);

  // مسیر پر (زیر نمودار)
  const areaPath = useMemo(() => {
    if (points.length === 0 || !showArea) return '';
    const baseY = padding.top + innerH;
    const first = points[0];
    const last = points[points.length - 1];
    return `${linePath} L ${last.x} ${baseY} L ${first.x} ${baseY} Z`;
  }, [linePath, points, innerH, padding.top, showArea]);

  // گرادیانت یکتا
  const gradientId = useMemo(
    () => `mini-chart-grad-${Math.random().toString(36).slice(2, 9)}`,
    []
  );

  // هندلرهای یکپارچه mouse/touch
  const handleInteraction = useCallback((clientX) => {
    if (!containerRef.current || points.length === 0) return;
    const idx = getClientXIndex(clientX, containerRef.current, points.length);
    if (idx !== null) setHoveredIdx(idx);
  }, [points.length]);

  const handleMouseMove = (e) => handleInteraction(e.clientX);
  const handleMouseLeave = () => setHoveredIdx(null);

  const handleTouchStart = (e) => {
    if (e.touches.length > 0) {
      handleInteraction(e.touches[0].clientX);
    }
  };
  const handleTouchMove = (e) => {
    if (e.touches.length > 0) {
      handleInteraction(e.touches[0].clientX);
    }
  };

  if (data.length === 0) {
    return (
      <div className={`text-center text-xs text-ink-400 dark:text-cream-500 py-8 ${className}`}>
        داده‌ای برای نمایش نیست
      </div>
    );
  }

  const gridLines = showGrid ? [0.25, 0.5, 0.75, 1] : [];
  const showTooltip = hoveredIdx !== null && points[hoveredIdx];

  return (
    <div className={`relative ${className}`} dir="rtl">
      <div
        ref={containerRef}
        className="relative w-full select-none"
        style={{
          height: `${chartHeight}px`,
          touchAction: 'pan-y',
        }}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
      >
        <svg
          viewBox={`0 0 ${width} ${chartHeight}`}
          preserveAspectRatio="none"
          className="w-full h-full pointer-events-none"
          style={{ direction: 'ltr' }}
        >
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={color} stopOpacity="0.35" />
              <stop offset="100%" stopColor={color} stopOpacity="0" />
            </linearGradient>
          </defs>

          {/* خطوط افقی — 🎨 Editorial grid */}
          {gridLines.map((ratio, i) => {
            const y = padding.top + innerH - ratio * innerH;
            return (
              <line
                key={i}
                x1={padding.left}
                x2={width - padding.right}
                y1={y}
                y2={y}
                stroke={CHART_COLORS.grid}
                strokeWidth="1"
                strokeDasharray="3 3"
                className="dark:!stroke-[#3D3B30]"
              />
            );
          })}

          {/* پرشدن زیر نمودار */}
          {showArea && areaPath && (
            <path d={areaPath} fill={`url(#${gradientId})`} />
          )}

          {/* خط اصلی */}
          <path
            d={linePath}
            fill="none"
            stroke={color}
            strokeWidth={isMobile ? 2.5 : 2.5}
            strokeLinecap="round"
            strokeLinejoin="round"
          />

          {/* نقطه‌ها — 🎨 Editorial dot fill (کاغذ روشن) */}
          {showDots && points.map((p, idx) => (
            <circle
              key={idx}
              cx={p.x}
              cy={p.y}
              r={hoveredIdx === idx ? (isMobile ? 6 : 5) : (isMobile ? 4 : 3.5)}
              fill={CHART_COLORS.dot}
              stroke={color}
              strokeWidth={isMobile ? 2.5 : 2.5}
              style={{ transition: 'r 0.15s ease' }}
            />
          ))}

          {/* خط عمودی در نقطه hover */}
          {showTooltip && (
            <line
              x1={points[hoveredIdx].x}
              x2={points[hoveredIdx].x}
              y1={padding.top}
              y2={padding.top + innerH}
              stroke={color}
              strokeWidth="1"
              strokeDasharray="2 3"
              opacity="0.5"
            />
          )}

          {/* برچسب‌های محور X — 🎨 Editorial ink-300 */}
          {points.map((p, idx) => {
            const maxLabels = isMobile ? 4 : 7;
            const step = Math.ceil(points.length / maxLabels);
            if (idx % step !== 0 && idx !== points.length - 1) return null;
            return (
              <text
                key={`label-${idx}`}
                x={p.x}
                y={chartHeight - (isMobile ? 6 : 8)}
                textAnchor="middle"
                fontSize={isMobile ? 10 : 10}
                fill={CHART_COLORS.axisLabel}
                className="dark:!fill-[#6B664F]"
                style={{ direction: 'rtl', fontWeight: '700' }}
              >
                {toPersianDateShort(p.item.date || p.item[labelKey])}
              </text>
            );
          })}
        </svg>

        {/* 🎨 Tooltip — Editorial ink-dark card */}
        {showTooltip && (
          <div
            className="absolute pointer-events-none z-10 animate-fadeIn"
            style={{
              left: `${getTooltipLeft(points[hoveredIdx].x, width)}%`,
              top: '0',
              transform: 'translate(-50%, -100%)',
            }}
          >
            <div className="bg-ink-900 dark:bg-ink-950 text-cream-50 rounded-2xl shadow-editorial px-3 py-2 text-center whitespace-nowrap border border-white/15 backdrop-blur-sm">
              <div className="font-display font-black text-[9px] sm:text-[10px] text-cream-300 mb-0.5 tabular-nums">
                {toPersianWeekday(points[hoveredIdx].item.date)} — {toPersianDateShort(points[hoveredIdx].item.date)}
              </div>
              <div
                className="font-display font-black text-xs sm:text-sm tabular-nums"
                style={{ color }}
              >
                {formatValue(points[hoveredIdx].value)}
              </div>
              {/* فلش پایین tooltip */}
              <div
                className="absolute left-1/2 -translate-x-1/2 top-full w-0 h-0 border-l-4 border-r-4 border-t-4 border-transparent"
                style={{ borderTopColor: CHART_COLORS.tooltipBg }}
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ============================================================
//  BarChart — نمودار میله‌ای
//
//  Props:
//    - data: آرایه‌ای از { label, value } یا { date, revenue }
//    - valueKey, labelKey
//    - color
//    - height, mobileHeight
//    - formatValue
//    - showValues: نمایش عدد روی هر میله
// ============================================================
export function BarChart({
  data = [],
  valueKey = 'value',
  labelKey = 'label',
  color = CHART_COLORS.brand, // 🎨 brand-500
  height = 220,
  mobileHeight = 180,
  formatValue = fmt,
  showValues = false,
  className = '',
}) {
  const [hoveredIdx, setHoveredIdx] = useState(null);
  const containerRef = useRef(null);

  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== 'undefined' ? window.innerWidth < 640 : false
  );

  React.useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 640);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  const chartHeight = isMobile ? mobileHeight : height;

  const padding = isMobile
    ? { top: 20, right: 8, bottom: 26, left: 8 }
    : { top: 24, right: 12, bottom: 32, left: 12 };
  const width = 600;
  const innerW = width - padding.left - padding.right;
  const innerH = chartHeight - padding.top - padding.bottom;

  const values = useMemo(() => data.map(d => Number(d[valueKey]) || 0), [data, valueKey]);
  const maxValue = Math.max(...values, 1);

  const bars = useMemo(() => {
    if (data.length === 0) return [];
    const gapRatio = isMobile ? 0.3 : 0.35;
    const stepX = innerW / data.length;
    const barWidth = stepX * (1 - gapRatio);

    return data.map((item, idx) => {
      const value = Number(item[valueKey]) || 0;
      const ratio = value / maxValue;
      const barH = ratio * innerH;
      const x = padding.left + idx * stepX + (stepX - barWidth) / 2;
      const y = padding.top + innerH - barH;
      return { x, y, w: barWidth, h: barH, value, item, idx, centerX: x + barWidth / 2 };
    });
  }, [data, valueKey, innerW, innerH, maxValue, padding.left, padding.top, isMobile]);

  // هندلرهای یکپارچه برای میله‌ها
  const handleInteraction = useCallback((clientX) => {
    if (!containerRef.current || bars.length === 0) return;
    const idx = getClientXIndex(clientX, containerRef.current, bars.length);
    if (idx !== null) setHoveredIdx(idx);
  }, [bars.length]);

  const handleMouseMove = (e) => handleInteraction(e.clientX);
  const handleMouseLeave = () => setHoveredIdx(null);

  const handleTouchStart = (e) => {
    if (e.touches.length > 0) handleInteraction(e.touches[0].clientX);
  };
  const handleTouchMove = (e) => {
    if (e.touches.length > 0) handleInteraction(e.touches[0].clientX);
  };

  if (data.length === 0) {
    return (
      <div className={`text-center text-xs text-ink-400 dark:text-cream-500 py-8 ${className}`}>
        داده‌ای برای نمایش نیست
      </div>
    );
  }

  const showTooltip = hoveredIdx !== null && bars[hoveredIdx];

  return (
    <div className={`relative ${className}`} dir="rtl">
      <div
        ref={containerRef}
        className="relative w-full select-none"
        style={{
          height: `${chartHeight}px`,
          touchAction: 'pan-y',
        }}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
      >
        <svg
          viewBox={`0 0 ${width} ${chartHeight}`}
          preserveAspectRatio="none"
          className="w-full h-full pointer-events-none"
          style={{ direction: 'ltr' }}
        >
          {/* خطوط افقی — 🎨 Editorial grid */}
          {[0.25, 0.5, 0.75, 1].map((ratio, i) => {
            const y = padding.top + innerH - ratio * innerH;
            return (
              <line
                key={i}
                x1={padding.left}
                x2={width - padding.right}
                y1={y}
                y2={y}
                stroke={CHART_COLORS.grid}
                strokeWidth="1"
                strokeDasharray="3 3"
                className="dark:!stroke-[#3D3B30]"
              />
            );
          })}

          {/* میله‌ها */}
          {bars.map((b) => {
            const isHovered = hoveredIdx === b.idx;
            return (
              <g key={b.idx}>
                <rect
                  x={b.x}
                  y={b.y}
                  width={b.w}
                  height={Math.max(b.h, 2)}
                  rx={isMobile ? 4 : 6}
                  fill={color}
                  opacity={isHovered ? 1 : 0.85}
                  style={{ transition: 'opacity 0.15s ease' }}
                />

                {/* عدد روی میله — 🎨 Editorial ink-400 + font-black */}
                {showValues && b.h > 20 && !isMobile && (
                  <text
                    x={b.centerX}
                    y={b.y - 4}
                    textAnchor="middle"
                    fontSize="10"
                    fill={CHART_COLORS.barText}
                    fontWeight="900"
                    className="dark:!fill-[#A8A29E]"
                  >
                    {formatValue(b.value)}
                  </text>
                )}
              </g>
            );
          })}

          {/* برچسب‌های محور X — 🎨 Editorial ink-300 */}
          {bars.map((b, idx) => {
            const maxLabels = isMobile ? 4 : 8;
            const step = Math.ceil(bars.length / maxLabels);
            if (idx % step !== 0 && idx !== bars.length - 1) return null;
            return (
              <text
                key={`label-${idx}`}
                x={b.centerX}
                y={chartHeight - (isMobile ? 6 : 8)}
                textAnchor="middle"
                fontSize="10"
                fill={CHART_COLORS.axisLabel}
                className="dark:!fill-[#6B664F]"
                style={{ direction: 'rtl', fontWeight: '700' }}
              >
                {toPersianDateShort(b.item.date || b.item[labelKey])}
              </text>
            );
          })}
        </svg>

        {/* 🎨 Tooltip نزدیک میله — Editorial ink-dark card */}
        {showTooltip && (
          <div
            className="absolute pointer-events-none z-10 animate-fadeIn"
            style={{
              left: `${getTooltipLeft(bars[hoveredIdx].centerX, width)}%`,
              top: '0',
              transform: 'translate(-50%, -100%)',
            }}
          >
            <div className="bg-ink-900 dark:bg-ink-950 text-cream-50 rounded-2xl shadow-editorial px-3 py-2 text-center whitespace-nowrap border border-white/15 backdrop-blur-sm">
              <div className="font-display font-black text-[9px] sm:text-[10px] text-cream-300 mb-0.5 tabular-nums">
                {toPersianWeekday(bars[hoveredIdx].item.date)} — {toPersianDateShort(bars[hoveredIdx].item.date)}
              </div>
              <div
                className="font-display font-black text-xs sm:text-sm tabular-nums"
                style={{ color }}
              >
                {formatValue(bars[hoveredIdx].value)}
              </div>
              <div
                className="absolute left-1/2 -translate-x-1/2 top-full w-0 h-0 border-l-4 border-r-4 border-t-4 border-transparent"
                style={{ borderTopColor: CHART_COLORS.tooltipBg }}
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ============================================================
//  SparkLine — نمودار خیلی کوچک برای کارت‌ها (بدون محور)
//  🎨 Editorial: رنگ پیش‌فرض brand
// ============================================================
export function SparkLine({
  data = [],
  valueKey = 'value',
  color = CHART_COLORS.brand, // 🎨 brand-500
  height = 40,
  width = 120,
  className = '',
}) {
  const values = data.map(d => Number(d[valueKey]) || 0);
  const maxValue = Math.max(...values, 1);
  const minValue = Math.min(...values, 0);
  const range = maxValue - minValue || 1;

  if (data.length < 2) {
    return <div className={className} style={{ height }} />;
  }

  const stepX = width / (data.length - 1);
  const points = values.map((v, i) => ({
    x: i * stepX,
    y: height - ((v - minValue) / range) * height,
  }));

  let path = `M ${points[0].x} ${points[0].y}`;
  for (let i = 1; i < points.length; i++) {
    const prev = points[i - 1];
    const curr = points[i];
    const cp1x = prev.x + (curr.x - prev.x) / 3;
    const cp2x = prev.x + (curr.x - prev.x) * 2 / 3;
    path += ` C ${cp1x} ${prev.y}, ${cp2x} ${curr.y}, ${curr.x} ${curr.y}`;
  }

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className={className}
      style={{ height: `${height}px`, width: '100%', direction: 'ltr' }}
      preserveAspectRatio="none"
    >
      <path
        d={path}
        fill="none"
        stroke={color}
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

// ============================================================
//  Export پیش‌فرض — LineChart (چون بیشتر استفاده می‌شه)
// ============================================================
export default LineChart;