const fmt = (n) => {
  if (n === null || n === undefined || n === '') return '۰';
  const num = Number(n);
  if (Number.isNaN(num)) return '۰';
  return Math.round(num).toLocaleString('fa-IR');
};

const fmtShort = (n) => {
  const num = Math.round(Number(n) || 0);
  if (num >= 1_000_000_000) return `${toFaDecimal(num / 1_000_000_000, 1)} میلیارد`;
  if (num >= 1_000_000) return `${toFaDecimal(num / 1_000_000, 1)} میلیون`;
  if (num >= 1_000) return `${toFaDecimal(num / 1_000, 0)} هزار`;
  return num.toLocaleString('fa-IR');
};

const toJsDate = (d) => {
  if (!d) return null;
  if (d instanceof Date) return isNaN(d.getTime()) ? null : d;
  if (typeof d.toDate === 'function') {
    const jsDate = d.toDate();
    return isNaN(jsDate.getTime()) ? null : jsDate;
  }
  const parsed = new Date(d);
  return isNaN(parsed.getTime()) ? null : parsed;
};

const toISO = (date) => {
  const d = toJsDate(date);
  if (!d) return null;
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

const formatDate = (iso) => {
  const d = toJsDate(iso);
  if (!d) return '—';
  return d.toLocaleDateString('fa-IR');
};

const formatRange = (start, end) => {
  if (!start && !end) return 'همه سفارشات (بدون فیلتر)';
  const s = formatDate(start);
  const e = formatDate(end);
  return `${s} تا ${e}`;
};

const daysBetween = (start, end) => {
  const s = toJsDate(start);
  const e = toJsDate(end);
  if (!s || !e) return null;
  const diff = Math.ceil((e - s) / (1000 * 60 * 60 * 24)) + 1;
  return diff > 0 ? diff : 0;
};

