function StatCard({
  icon,
  label,
  value,
  unit,
  color = 'brand',
  hint,
  changePercent,
  isExpense = false,
}) {
  const c = STAT_COLORS[color] || STAT_COLORS.brand;

  const hasChange = changePercent !== undefined && changePercent !== null;
  const isPositive = changePercent > 0;
  const isGood = isExpense ? !isPositive : isPositive;

  return (
    <div
      className={`${c} text-white rounded-3xl p-3 sm:p-4 shadow-soft transition-all hover:shadow-lifted hover:-translate-y-0.5 active:scale-[0.98] relative overflow-hidden`}
    >
      <div
        className="absolute -top-8 -left-8 w-24 h-24 bg-white/10 rounded-full"
        aria-hidden="true"
      />

      <div className="relative">
        <div className="flex items-start justify-between mb-2 gap-2">
          <span
            className="text-xl sm:text-2xl flex-shrink-0"
            aria-hidden="true"
          >
            {icon}
          </span>
          <div className="flex flex-col items-end gap-1 min-w-0">
            <span className="text-[10px] opacity-90 font-black text-left leading-tight">
              {label}
            </span>
            {hasChange && changePercent !== 0 && (
              <span
                className={`text-[9px] font-black px-1.5 py-0.5 rounded-full whitespace-nowrap font-num tabular-nums ${
                  isGood
                    ? 'bg-accent-400/30 text-accent-100'
                    : 'bg-rose-400/30 text-rose-100'
                }`}
              >
                {isPositive ? '▲' : '▼'}{' '}
                {toFaDecimal(Math.abs(changePercent), 1)}٪
              </span>
            )}
          </div>
        </div>
        <div className="text-base sm:text-xl font-display font-black truncate font-num tabular-nums">
          {value}
        </div>
        {unit && (
          <div className="text-[10px] opacity-80 mt-0.5 font-bold">{unit}</div>
        )}
        {hint && (
          <div className="text-[10px] opacity-75 mt-1 border-t border-white/20 pt-1 truncate font-bold">
            {hint}
          </div>
        )}
      </div>
    </div>
  );
}

