// frontend/src/user/publicAxios.js
// ============================================================
//  Public Axios — بدون interceptor ادمین
//  ✅ FIX: حذف لاگ کردن داده‌های حساس (password, token, ...)
//  درخواست‌های نیازمند لاگین با `userAxios` انجام می‌شن.
// ============================================================
import axios from 'axios';
import { API_BASE } from '../config/api';

// برای سازگاری با فایل‌هایی که API_BASE را از اینجا import می‌کنند
export { API_BASE };

// فعال/غیرفعال کردن لاگ‌ها برای دیباگ
const DEBUG_AXIOS =
  typeof process !== 'undefined' &&
  process.env &&
  process.env.NODE_ENV !== 'production';

const publicAxios = axios.create({
  baseURL: API_BASE,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// ============================================================
//  Interceptor درخواست — لاگ امن (بدون data)
// ============================================================
publicAxios.interceptors.request.use(
  (config) => {
    if (DEBUG_AXIOS) {
      console.log('📤 [publicAxios] Request:', {
        method: config.method?.toUpperCase(),
        url: config.url,
        hasData: Boolean(config.data),
      });
    }
    return config;
  },
  (error) => {
    if (DEBUG_AXIOS) {
      console.error('❌ [publicAxios] Request error:', {
        message: error?.message,
      });
    }
    return Promise.reject(error);
  }
);

// ============================================================
//  Interceptor پاسخ — مدیریت خطاها
// ============================================================
publicAxios.interceptors.response.use(
  (response) => {
    if (DEBUG_AXIOS) {
      console.log('✅ [publicAxios] Response:', {
        status: response.status,
        url: response.config.url,
      });
    }
    return response;
  },
  (error) => {
    // ===== حالت ۱: timeout =====
    if (error.code === 'ECONNABORTED') {
      console.warn('⏱️  [publicAxios] Request timeout');
      error.userMessage = 'درخواست طول کشید. لطفاً دوباره تلاش کنید.';
      return Promise.reject(error);
    }

    // ===== حالت ۲: network error (سرور خاموش) =====
    if (!error.response) {
      console.warn('🌐 [publicAxios] Network error (no response)');
      error.userMessage =
        'ارتباط با سرور برقرار نشد. لطفاً اتصال اینترنت و سرور را بررسی کنید.';
      return Promise.reject(error);
    }

    // ===== حالت ۳: خطاهای HTTP =====
    const { status, data } = error.response;

    // ---- ۴۲۲ (Validation Error از Pydantic) ----
    if (status === 422) {
      const detail = data?.detail;
      if (Array.isArray(detail)) {
        error.response.data.detail = detail
          .map((e) => {
            const field = Array.isArray(e.loc) ? e.loc.slice(-1)[0] : '';
            return field ? `${field}: ${e.msg}` : e.msg;
          })
          .join(' | ');
      } else if (typeof detail === 'object' && detail !== null) {
        error.response.data.detail = Object.entries(detail)
          .map(([key, val]) => `${key}: ${val}`)
          .join(' | ');
      } else if (typeof detail === 'string') {
        // از قبل string است
      } else {
        error.response.data.detail = 'خطای اعتبارسنجی در داده‌های ارسالی';
      }
    }

    // ---- ۴۰۰ (Bad Request از سمت ما) ----
    else if (status === 400) {
      if (!data?.detail) {
        error.response.data.detail = 'درخواست نامعتبر است.';
      }
    }

    // ---- ۴۰۱ (Unauthorized) ----
    else if (status === 401) {
      if (!data?.detail) {
        error.response.data.detail = 'دسترسی غیرمجاز.';
      }
    }

    // ---- ۴۰۳ (Forbidden) ----
    else if (status === 403) {
      if (!data?.detail) {
        error.response.data.detail = 'شما به این بخش دسترسی ندارید.';
      }
    }

    // ---- ۴۰۴ (Not Found) ----
    else if (status === 404) {
      if (!data?.detail) {
        error.response.data.detail = 'موردی یافت نشد.';
      }
    }

    // ---- ۵۰۰ (Internal Server Error) ----
    else if (status >= 500) {
      if (!data?.detail) {
        error.response.data.detail =
          'خطای داخلی سرور. لطفاً با پشتیبانی تماس بگیرید.';
      }
    }

    // ===== لاگ خطا (بدون data) =====
    if (DEBUG_AXIOS) {
      console.error('❌ [publicAxios] Response error:', {
        status,
        url: error.config?.url,
        detail: error.response?.data?.detail,
      });
    }

    return Promise.reject(error);
  }
);

export default publicAxios;