// frontend/src/config/api.js
// ============================================================
//  منبع واحد API_BASE برای کل فرانت‌اند
//
//  ✅ FIX v2 (Flask migration):
//    - کامنت‌ها به‌روزرسانی شدن (FastAPI → Flask)
//    - API_BASE از env var خونده می‌شه (production-ready)
//
//  برای production:
//    1. فایل .env.production در پوشه frontend بساز:
//       REACT_APP_API_BASE=https://api.your-domain.com
//    2. npm run build
//
//  برای development:
//    - fallback خودکار به http://localhost:8000
//    - یا فایل .env.development بساز
// ============================================================

// آدرس بک‌اند Flask
// در dev: http://localhost:8000
// در production: از env var خونده می‌شه
export const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:8000';

// پیشوند API‌های عمومی و کاربر
export const API_PREFIX = '/api';

// پیشوند API‌های ادمین
export const ADMIN_PREFIX = '/admin';

// ============================================================
//  🖼️ resolveAssetUrl — تبدیل URL نسبی به URL کامل
// ============================================================
//  - undefined/null/'' → ''
//  - URL مطلق (http:// یا https://) → همان
//  - مسیر نسبی با '/' ابتدا → API_BASE + url
//  - مسیر بدون '/' ابتدا → همان (فرض می‌کنیم URL نسبی یا data: URL)
//
//  مثال:
//    resolveAssetUrl('/uploads/avatars/x.jpg')
//      → 'http://localhost:8000/uploads/avatars/x.jpg'
//    resolveAssetUrl('https://cdn.example.com/y.png')
//      → 'https://cdn.example.com/y.png'
//    resolveAssetUrl(undefined)
//      → ''
// ============================================================
export function resolveAssetUrl(url) {
  if (!url) return '';
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('/')) return `${API_BASE}${url}`;
  return url;
}