// frontend/src/user/components/SiteHeader.jsx
// 🛒 v5.1 (Miko Warm Palette):
//   ✅ آیکون‌های هاردکد (☰ ✕ ← ▼ SVG) به SiteImage منتقل شدند
//   - STORAGE_KEYS / SESSION_KEYS / AUTH_EVENT / USER_DATA_EVENT از constants
//   - UserAvatar از API_BASE مشترک برای ساخت URL استفاده می‌کند

import React, { useState, useEffect, useRef, useCallback, memo } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';

import { SiteImage } from '../../utils/SiteImage';
import { useCart } from '../hooks/useCart';
import { toFa } from '../../utils/numbers';
import { API_BASE } from '../../config/api';
import {
  STORAGE_KEYS,
  SESSION_KEYS,
  AUTH_EVENT,
  USER_DATA_EVENT,
} from '../../constants/storageKeys';

// ============================================================
//  CONSTANTS
// ============================================================
const HEADER_HEIGHT = { normal: 96, offset: 112 };

const BRAND = {
  name: 'میکو',
  tagline: 'غذای سالم و علمی',
  logo: '/logo-miko.png',
};

const NAV_ITEMS = [
  { label: 'ثبت سفارش',        hash: '#order-form-section', primary: true },
  { label: 'چطور کار می‌کنه',   hash: '#how-it-works' },
  { label: 'چرا میکو؟',         hash: '#benefits' },
  { label: 'نظر مشتریان',       hash: '#testimonials' },
  { label: 'سؤالات متداول',     hash: '#faq' },
];

const SECTIONS = [
  { label: 'محاسبه رژیم',       hash: '#quick-calculator',  iconKey: 'icon_calculator',    fallbackIcon: '🧮' },
  { label: 'چطور کار می‌کنه',    hash: '#how-it-works',      iconKey: 'icon_how_it_works',  fallbackIcon: '💡' },
  { label: 'چرا ما',            hash: '#benefits',          iconKey: 'icon_benefits',      fallbackIcon: '⭐' },
  { label: 'نظرات مشتریان',     hash: '#testimonials',      iconKey: 'icon_testimonials',  fallbackIcon: '💬' },
  { label: 'سؤالات متداول',     hash: '#faq',               iconKey: 'icon_faq',           fallbackIcon: '❓' },
  { label: 'فرم سفارش',         hash: '#order-form-section', iconKey: 'icon_order_form',    fallbackIcon: '📝' },
];

const USER_MENU_ITEMS = [
  { label: 'داشبورد',       href: '/panel',                    iconKey: 'icon_dashboard',   fallbackIcon: '🏠' },
  { label: 'سفارش‌های من',  href: '/panel/orders',             iconKey: 'icon_orders',      fallbackIcon: '📦' },
  { label: 'سگ‌های من',     href: '/panel/dogs',               iconKey: 'icon_dog',         fallbackIcon: '🐕' },
  { label: 'ثبت نظر',        href: '/panel/testimonials/new',   iconKey: 'icon_testimonial', fallbackIcon: '⭐' },
  { label: 'تیکت‌ها',       href: '/panel/tickets',            iconKey: 'icon_ticket',      fallbackIcon: '🎫' },
  { label: 'پروفایل',        href: '/panel/profile',            iconKey: 'icon_profile',     fallbackIcon: '👤' },
];

// ============================================================
//  Helper: resolve any avatar URL to a full absolute URL
// ============================================================
function resolveAssetUrl(url) {
  if (!url) return '';
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('/')) return `${API_BASE}${url}`;
  return url;
}

// ============================================================
//  Hook: prefers-reduced-motion
// ============================================================
function usePrefersReducedMotion() {
  const [prefersReduced, setPrefersReduced] = useState(false);
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const handler = () => setPrefersReduced(mq.matches);
    handler();
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, []);
  return prefersReduced;
}

// ============================================================
//  🎨 BrandLogo
// ============================================================
const BrandLogo = memo(function BrandLogo({ onClick = null }) {
  const content = (
    <div className="flex items-center gap-2 sm:gap-3.5 min-w-0 group">
      <SiteImage
        imageKey="header_logo"
        fallback={BRAND.logo}
        alt={BRAND.name}
        className="w-11 h-11 sm:w-14 sm:h-14 object-contain transition-transform duration-500 flex-shrink-0 group-hover:scale-105"
        showPlaceholder={true}
        placeholderContent={
          <div className="w-11 h-11 sm:w-14 sm:h-14 rounded-2xl bg-gradient-to-br from-miko-rust to-miko-pumpkin flex items-center justify-center text-white font-black text-xl sm:text-2xl flex-shrink-0 shadow-miko">
            م
          </div>
        }
      />

      <div className="hidden sm:flex flex-col justify-center min-w-0 leading-none">
        <span className="font-miko-gradient text-[30px] lg:text-[34px] leading-none">
          {BRAND.name}
        </span>
        <span className="text-[11px] lg:text-[12px] font-bold tracking-[0.02em] text-miko-olive dark:text-miko-carrot mt-1.5 leading-none">
          {BRAND.tagline}
        </span>
      </div>
    </div>
  );

  if (onClick) {
    return (
      <button
        type="button"
        onClick={onClick}
        className="text-right"
        aria-label={`صفحه اصلی ${BRAND.name}`}
      >
        {content}
      </button>
    );
  }

  return (
    <Link to="/" aria-label={`صفحه اصلی ${BRAND.name}`}>
      {content}
    </Link>
  );
});

// ============================================================
//  UserAvatar
// ============================================================
const UserAvatar = memo(function UserAvatar({ userData, size = 'md' }) {
  const [imgError, setImgError] = useState(false);

  const sizeClasses = {
    sm: 'w-9 h-9 text-xs',
    md: 'w-11 h-11 text-sm',
    lg: 'w-12 h-12 text-base',
    xl: 'w-14 h-14 text-lg',
  };

  const sz = sizeClasses[size] || sizeClasses.md;
  const avatarUrl = userData?.avatar_url;
  const initial = (userData?.full_name || userData?.username || '?')
    .charAt(0)
    .toUpperCase();

  const fullUrl = resolveAssetUrl(avatarUrl);

  if (fullUrl && !imgError) {
    return (
      <div
        className={`${sz} rounded-2xl overflow-hidden flex-shrink-0 ring-2 ring-miko-carrot/30 dark:ring-miko-carrot/20`}
      >
        <img
          src={fullUrl}
          alt={userData.full_name || userData.username}
          className="w-full h-full object-cover"
          onError={() => setImgError(true)}
        />
      </div>
    );
  }

  return (
    <div
      className={`${sz} rounded-2xl bg-gradient-to-br from-miko-rust to-miko-pumpkin flex items-center justify-center text-white font-black flex-shrink-0 shadow-miko`}
    >
      {initial}
    </div>
  );
});

// ============================================================
//  scrollToHash
// ============================================================
function scrollToHash(hash, prefersReduced = false) {
  const id = hash.replace('#', '');
  const el = document.getElementById(id);
  if (!el) return false;
  const top =
    el.getBoundingClientRect().top + window.pageYOffset - HEADER_HEIGHT.offset;
  window.scrollTo({ top, behavior: prefersReduced ? 'auto' : 'smooth' });
  return true;
}

// ============================================================
//  NavLinks
// ============================================================
function NavLinks({ activeHash, onNavigate, prefersReduced }) {
  return (
    <nav
      className="hidden lg:flex items-center gap-1"
      aria-label="ناوبری اصلی"
    >
      {NAV_ITEMS.map((item) => {
        const isActive = activeHash === item.hash;
        const isPrimary = item.primary === true;

        if (isPrimary) {
          return (
            <button
              key={item.hash}
              type="button"
              onClick={() => onNavigate(item.hash)}
              className={`
                group relative
                inline-flex items-center justify-center
                px-4 py-2.5 ml-2
                text-[14px] font-black
                whitespace-nowrap
                rounded-xl
                border-2
                transition-all duration-300
                ${
                  isActive
                    ? 'bg-gradient-to-br from-miko-rust to-miko-pumpkin text-white border-transparent shadow-miko'
                    : 'bg-miko-cream/60 dark:bg-miko-rust/10 text-miko-rust dark:text-miko-carrot border-miko-carrot/30 dark:border-miko-rust/30 hover:bg-miko-carrot/15 dark:hover:bg-miko-rust/20 hover:border-miko-carrot/60 dark:hover:border-miko-rust/50'
                }
                ${
                  prefersReduced
                    ? ''
                    : 'hover:-translate-y-0.5 active:translate-y-0'
                }
              `}
            >
              <span className="relative z-10">{item.label}</span>

              {isActive && (
                <span
                  className="absolute inset-0 rounded-xl bg-gradient-to-br from-white/15 to-transparent pointer-events-none"
                  aria-hidden="true"
                />
              )}
            </button>
          );
        }

        return (
          <button
            key={item.hash}
            type="button"
            onClick={() => onNavigate(item.hash)}
            className={`
              group relative
              px-4 py-3
              text-[15px] font-bold
              whitespace-nowrap
              rounded-xl
              transition-all duration-300
              ${
                isActive
                  ? 'text-miko-rust dark:text-miko-carrot'
                  : 'text-miko-dark/80 dark:text-miko-cream/90 hover:text-miko-rust dark:hover:text-miko-carrot'
              }
            `}
          >
            <span className="relative z-10">{item.label}</span>

            <span
              className={`
                absolute inset-0 rounded-xl
                bg-miko-carrot/10 dark:bg-miko-rust/15
                opacity-0
                transition-opacity duration-300
                ${isActive ? '' : 'group-hover:opacity-100'}
              `}
              aria-hidden="true"
            />

            <span
              className={`
                absolute bottom-1.5 right-1/2 translate-x-1/2
                w-1.5 h-1.5 rounded-full
                bg-miko-rust
                transition-all duration-300
                ${isActive ? 'opacity-100 scale-100' : 'opacity-0 scale-0'}
              `}
              aria-hidden="true"
            />
          </button>
        );
      })}
    </nav>
  );
}

// ============================================================
//  🛒 CartButton
// ============================================================
function CartButton({ count, onClick, compact = false }) {
  const hasItems = count > 0;

  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={hasItems ? `سبد خرید، ${count} آیتم` : 'سبد خرید (خالی)'}
      className={`
        relative
        inline-flex items-center justify-center
        ${compact ? 'w-12 h-12' : 'h-12 px-3'}
        rounded-2xl
        border-2
        transition-all duration-300
        focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-miko-rust/40
        ${
          hasItems
            ? 'bg-miko-cream dark:bg-miko-rust/10 text-miko-rust dark:text-miko-carrot border-miko-carrot/30 dark:border-miko-rust/30 hover:bg-miko-carrot/15 dark:hover:bg-miko-rust/20 hover:-translate-y-0.5 active:translate-y-0'
            : 'bg-transparent text-miko-dark/80 dark:text-miko-cream/90 border-transparent hover:bg-miko-carrot/10 dark:hover:bg-miko-rust/15'
        }
      `}
    >
      <SiteImage
        imageKey="icon_cart"
        showPlaceholder
        placeholderContent={<span className="text-xl" aria-hidden="true">🛒</span>}
        className="w-5 h-5 object-contain"
      />

      {hasItems && (
        <span
          className="
            absolute -top-1.5 -left-1.5
            min-w-[20px] h-5 px-1.5
            rounded-full
            bg-miko-rust text-white
            text-[11px] font-black
            flex items-center justify-center
            ring-2 ring-miko-cream dark:ring-ink-900
            pointer-events-none
          "
          aria-hidden="true"
        >
          {toFa(count)}
        </span>
      )}
    </button>
  );
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function SiteHeader() {
  const navigate = useNavigate();
  const location = useLocation();
  const prefersReduced = usePrefersReducedMotion();

  // 🛒 cart state
  const cart = useCart();

  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userData, setUserData] = useState({});
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeHash, setActiveHash] = useState('');

  const userMenuRef = useRef(null);
  const sidebarRef = useRef(null);

  useEffect(() => {
    const syncUser = () => {
      try {
        const token = localStorage.getItem(STORAGE_KEYS.USER_TOKEN);
        const data = JSON.parse(
          localStorage.getItem(STORAGE_KEYS.USER_DATA) || '{}'
        );
        setIsLoggedIn(!!token);
        setUserData(data);
      } catch {
        setIsLoggedIn(false);
        setUserData({});
      }
    };
    syncUser();
    window.addEventListener('storage', syncUser);
    window.addEventListener(USER_DATA_EVENT, syncUser);
    window.addEventListener(AUTH_EVENT, syncUser);
    return () => {
      window.removeEventListener('storage', syncUser);
      window.removeEventListener(USER_DATA_EVENT, syncUser);
      window.removeEventListener(AUTH_EVENT, syncUser);
    };
  }, []);

  useEffect(() => {
    let ticking = false;
    const handler = () => {
      if (!ticking) {
        window.requestAnimationFrame(() => {
          setScrolled(window.scrollY > 20);
          ticking = false;
        });
        ticking = true;
      }
    };
    handler();
    window.addEventListener('scroll', handler, { passive: true });
    return () => window.removeEventListener('scroll', handler);
  }, []);

  useEffect(() => {
    if (location.pathname !== '/') {
      setActiveHash('');
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) setActiveHash(`#${entry.target.id}`);
        });
      },
      { rootMargin: '-30% 0px -60% 0px', threshold: 0 }
    );
    ['how-it-works', 'benefits', 'testimonials', 'faq'].forEach((id) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });
    return () => observer.disconnect();
  }, [location.pathname]);

  useEffect(() => {
    setSidebarOpen(false);
    setUserMenuOpen(false);
  }, [location.pathname]);

  useEffect(() => {
    if (!userMenuOpen) return;
    const handler = (e) => {
      if (userMenuRef.current && !userMenuRef.current.contains(e.target)) {
        setUserMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    document.addEventListener('touchstart', handler);
    return () => {
      document.removeEventListener('mousedown', handler);
      document.removeEventListener('touchstart', handler);
    };
  }, [userMenuOpen]);

  useEffect(() => {
    if (!sidebarOpen) return;
    const originalOverflow = document.body.style.overflow;
    const originalPaddingRight = document.body.style.paddingRight;
    const scrollbarWidth =
      window.innerWidth - document.documentElement.clientWidth;
    document.body.style.overflow = 'hidden';
    if (scrollbarWidth > 0)
      document.body.style.paddingRight = `${scrollbarWidth}px`;
    const handleEsc = (e) => {
      if (e.key === 'Escape') setSidebarOpen(false);
    };
    document.addEventListener('keydown', handleEsc);
    return () => {
      document.body.style.overflow = originalOverflow || '';
      document.body.style.paddingRight = originalPaddingRight || '';
      document.removeEventListener('keydown', handleEsc);
    };
  }, [sidebarOpen]);

  const handleLogout = useCallback(() => {
    localStorage.removeItem(STORAGE_KEYS.USER_TOKEN);
    localStorage.removeItem(STORAGE_KEYS.USER_DATA);
    try {
      sessionStorage.removeItem(SESSION_KEYS.PENDING_ORDER);
      sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
      sessionStorage.removeItem(SESSION_KEYS.QUICK_FORM);
      sessionStorage.removeItem(SESSION_KEYS.QUICK_RESULT);
      sessionStorage.removeItem(SESSION_KEYS.LAST_DELIVERY);
    } catch { /* silent */ }
    setUserMenuOpen(false);
    setSidebarOpen(false);
    setShowLogoutConfirm(false);
    setIsLoggedIn(false);
    setUserData({});
    window.dispatchEvent(new Event(AUTH_EVENT));
    window.dispatchEvent(new Event(USER_DATA_EVENT));
    navigate('/', { replace: true });
  }, [navigate]);

  const handleSectionClick = useCallback(
    (hash) => {
      setSidebarOpen(false);
      setUserMenuOpen(false);
      if (location.pathname === '/') {
        requestAnimationFrame(() => {
          setTimeout(() => scrollToHash(hash, prefersReduced), 200);
        });
      } else {
        navigate('/' + hash);
      }
    },
    [location.pathname, navigate, prefersReduced]
  );

  const handleCartClick = useCallback(() => {
    setSidebarOpen(false);
    setUserMenuOpen(false);
    navigate('/cart');
  }, [navigate]);

  const isHeroPage = location.pathname === '/';

  const headerBg = scrolled
    ? 'bg-miko-cream/95 dark:bg-ink-900/90 backdrop-blur-2xl border-b border-miko-carrot/20 dark:border-dark-700/70 shadow-soft'
    : 'bg-miko-cream/70 dark:bg-ink-900/50 backdrop-blur-md border-b border-transparent';

  return (
    <>
      <header
        className={`fixed top-0 left-0 right-0 z-40 transition-all duration-500 ease-smooth safe-top ${headerBg}`}
      >
        <div className="max-w-editorial mx-auto px-4 sm:px-8 lg:px-10">
          <div className="h-[96px] flex items-center justify-between gap-3 sm:gap-6">

            {/* START (right in RTL) */}
            <div className="flex items-center gap-2 sm:gap-6 flex-shrink-0 min-w-0">
              <button
                type="button"
                onClick={() => setSidebarOpen(true)}
                className="
                  lg:hidden
                  w-11 h-11 sm:w-12 sm:h-12 flex items-center justify-center
                  rounded-2xl
                  text-miko-dark/80 dark:text-miko-cream/90
                  hover:bg-miko-carrot/10 dark:hover:bg-miko-rust/15
                  active:bg-miko-carrot/20
                  transition-colors
                  flex-shrink-0
                "
                aria-label="باز کردن منو"
              >
                <SiteImage
                  imageKey="icon_menu"
                  showPlaceholder={true}
                  placeholderContent={
                    <span className="text-2xl" aria-hidden="true">☰</span>
                  }
                  className="w-6 h-6 object-contain"
                />
              </button>

              <BrandLogo />

              <NavLinks
                activeHash={activeHash}
                onNavigate={handleSectionClick}
                prefersReduced={prefersReduced}
              />
            </div>

            {/* END (left in RTL) */}
            <div className="flex items-center gap-2 sm:gap-3 flex-shrink-0">

              <CartButton count={cart.totalCount} onClick={handleCartClick} />

              {isLoggedIn ? (
                <div className="relative" ref={userMenuRef}>
                  <button
                    type="button"
                    onClick={() => setUserMenuOpen((v) => !v)}
                    className={`
                      flex items-center gap-3
                      h-12 sm:h-14 pl-1 pr-2 sm:pl-2 sm:pr-3
                      rounded-2xl
                      border-2
                      transition-all duration-300
                      ${
                        userMenuOpen
                          ? 'bg-white dark:bg-ink-800 border-miko-carrot dark:border-miko-rust/40 shadow-miko ring-4 ring-miko-rust/10'
                          : 'bg-white dark:bg-ink-800 border-miko-carrot/30 dark:border-dark-700 hover:border-miko-carrot dark:hover:border-miko-rust/40 hover:shadow-soft'
                      }
                    `}
                    aria-label="منوی کاربر"
                    aria-expanded={userMenuOpen}
                    aria-haspopup="menu"
                  >
                    <UserAvatar userData={userData} size="md" />

                    <div className="hidden sm:flex flex-col items-start min-w-0 max-w-[140px] text-right leading-tight">
                      <span className="text-[10px] font-medium text-miko-dark/50 dark:text-miko-cream/60 mb-0.5">
                        خوش آمدید
                      </span>
                      <span className="text-[13px] font-black text-miko-dark dark:text-miko-cream truncate w-full">
                        {userData.full_name || userData.username || 'کاربر'}
                      </span>
                    </div>

                    <span
                      className={`
                        hidden sm:inline-flex items-center justify-center
                        w-5 h-5 rounded-full
                        bg-miko-carrot/15 dark:bg-miko-rust/20
                        text-miko-olive dark:text-miko-carrot
                        transition-transform duration-300
                        ${userMenuOpen ? 'rotate-180' : ''}
                      `}
                      aria-hidden="true"
                    >
                      <SiteImage
                        imageKey="icon_arrow_down"
                        showPlaceholder={true}
                        placeholderContent={<span className="text-[10px]">▼</span>}
                        className="w-3 h-3 object-contain"
                      />
                    </span>
                  </button>

                  {userMenuOpen && (
                    <div
                      role="menu"
                      className="
                        absolute left-0 top-full mt-3 sm:mt-4
                        w-[min(20rem,calc(100vw-2rem))]
                        bg-miko-cream dark:bg-ink-800
                        rounded-3xl
                        border border-miko-carrot/30 dark:border-dark-700
                        shadow-editorial
                        overflow-hidden z-50 animate-fade-down
                      "
                    >
                      <div className="p-5 bg-gradient-to-bl from-miko-cream to-miko-carrot/15 dark:from-miko-rust/10 dark:to-miko-rust/5 border-b border-miko-carrot/20 dark:border-dark-700">
                        <div className="flex items-center gap-4">
                          <UserAvatar userData={userData} size="xl" />
                          <div className="min-w-0 flex-1">
                            <div className="font-display font-black text-miko-dark dark:text-miko-cream text-[15px] truncate">
                              {userData.full_name || userData.username}
                            </div>
                            <div
                              className="text-[12px] text-miko-rust dark:text-miko-carrot font-mono mt-1 truncate"
                              dir="ltr"
                            >
                              @{userData.username}
                            </div>
                          </div>
                        </div>
                      </div>

                      <div className="p-2">
                        {USER_MENU_ITEMS.map((item) => (
                          <Link
                            key={item.href}
                            to={item.href}
                            role="menuitem"
                            onClick={() => setUserMenuOpen(false)}
                            className="
                              flex items-center gap-4
                              px-4 py-3 min-h-[48px]
                              rounded-2xl
                              hover:bg-miko-carrot/10 dark:hover:bg-miko-rust/15
                              active:bg-miko-carrot/20
                              transition
                              text-[14px] font-medium text-miko-dark dark:text-miko-cream
                            "
                          >
                            <div className="w-5 text-center text-base flex-shrink-0 flex items-center justify-center">
                              <SiteImage
                                imageKey={item.iconKey}
                                showPlaceholder={true}
                                placeholderContent={<span>{item.fallbackIcon}</span>}
                                className="w-5 h-5 object-contain"
                              />
                            </div>
                            <span className="flex-1 truncate">{item.label}</span>
                          </Link>
                        ))}

                        <div className="my-2.5 border-t border-miko-carrot/20 dark:border-dark-700" />

                        <button
                          type="button"
                          role="menuitem"
                          onClick={() => setShowLogoutConfirm(true)}
                          className="
                            w-full flex items-center gap-4
                            px-4 py-3 min-h-[48px]
                            rounded-2xl
                            hover:bg-rose-50 dark:hover:bg-rose-500/10
                            active:bg-rose-100
                            transition
                            text-[14px] font-bold text-rose-600 dark:text-rose-400
                          "
                        >
                          <div className="w-5 text-center text-base flex-shrink-0 flex items-center justify-center">
                            <SiteImage
                              imageKey="icon_logout"
                              showPlaceholder={true}
                              placeholderContent={<span aria-hidden="true">🚪</span>}
                              className="w-5 h-5 object-contain"
                            />
                          </div>
                          <span className="flex-1 text-right">خروج از حساب</span>
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ) : (
                <>
                  <Link
                    to="/login"
                    className="
                      hidden sm:inline-flex items-center justify-center
                      h-12 px-5
                      text-[14px] font-bold
                      text-miko-olive dark:text-miko-carrot
                      rounded-2xl
                      transition-all duration-300
                      hover:bg-miko-carrot/10 dark:hover:bg-miko-rust/15
                    "
                  >
                    ورود
                  </Link>

                  <Link
                    to="/register"
                    className="
                      hidden md:inline-flex items-center justify-center
                      h-12 px-6
                      text-[14px] font-black
                      bg-gradient-to-br from-miko-rust to-miko-pumpkin
                      text-white
                      rounded-2xl
                      transition-all duration-300
                      hover:-translate-y-0.5 active:translate-y-0
                      shadow-miko
                    "
                  >
                    ثبت‌نام
                  </Link>
                </>
              )}
            </div>
          </div>
        </div>
      </header>

      {!isHeroPage && (
        <div
          className="h-[96px]"
          aria-hidden="true"
          style={{ paddingTop: 'env(safe-area-inset-top, 0px)' }}
        />
      )}

      {/* SIDEBAR (موبایل) */}
      <div
        className={`fixed inset-0 z-50 transition-opacity duration-300 ${
          sidebarOpen
            ? 'pointer-events-auto opacity-100'
            : 'pointer-events-none opacity-0'
        }`}
        aria-hidden={!sidebarOpen}
      >
        <div
          className="absolute inset-0 bg-ink-900/60 backdrop-blur-sm"
          onClick={() => setSidebarOpen(false)}
          aria-hidden="true"
        />

        <aside
          ref={sidebarRef}
          className={`
            absolute top-0 right-0 h-full h-[100dvh]
            w-[85vw] max-w-sm
            bg-miko-cream dark:bg-ink-900
            shadow-2xl flex flex-col
            transition-transform duration-500 ease-smooth
            ${sidebarOpen ? 'translate-x-0' : 'translate-x-full'}
          `}
          style={{
            paddingTop: 'env(safe-area-inset-top, 0px)',
            paddingBottom: 'env(safe-area-inset-bottom, 0px)',
          }}
          aria-label="منوی اصلی"
        >
          <div className="flex items-center justify-between p-4 sm:p-5 border-b border-miko-carrot/20 dark:border-dark-700 flex-shrink-0">
            <BrandLogo onClick={() => setSidebarOpen(false)} />
            <button
              type="button"
              onClick={() => setSidebarOpen(false)}
              className="w-11 h-11 flex items-center justify-center rounded-xl hover:bg-miko-carrot/10 dark:hover:bg-miko-rust/15 transition text-miko-dark/80 dark:text-miko-cream/90 flex-shrink-0"
              aria-label="بستن منو"
            >
              <SiteImage
                imageKey="icon_close"
                showPlaceholder={true}
                placeholderContent={<span className="text-lg">✕</span>}
                className="w-5 h-5 object-contain"
              />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto overscroll-contain">
            {isLoggedIn && (
              <div className="p-4 sm:p-5 border-b border-miko-carrot/20 dark:border-dark-700">
                <Link
                  to="/panel/profile"
                  onClick={() => setSidebarOpen(false)}
                  className="
                    flex items-center gap-4 p-3.5 sm:p-4
                    bg-gradient-to-bl from-miko-cream to-miko-carrot/15
                    dark:from-miko-rust/10 dark:to-miko-rust/5
                    rounded-3xl
                    border border-miko-carrot/30 dark:border-miko-rust/20
                    transition-all group
                  "
                >
                  <UserAvatar userData={userData} size="xl" />
                  <div className="min-w-0 flex-1">
                    <div className="font-black text-miko-dark dark:text-miko-cream text-[15px] truncate">
                      {userData.full_name || userData.username}
                    </div>
                    <div
                      className="text-[12px] text-miko-rust dark:text-miko-carrot font-mono truncate mt-1"
                      dir="ltr"
                    >
                      @{userData.username}
                    </div>
                  </div>
                  <SiteImage
                    imageKey="icon_arrow_left"
                    showPlaceholder={true}
                    placeholderContent={<span className="text-miko-carrot text-sm">←</span>}
                    className="w-4 h-4 object-contain flex-shrink-0"
                  />
                </Link>
              </div>
            )}

            {cart.totalCount > 0 && (
              <nav className="px-3 sm:px-4 pt-4 pb-1">
                <Link
                  to="/cart"
                  onClick={() => setSidebarOpen(false)}
                  className="
                    flex items-center gap-4
                    p-3.5 sm:p-4
                    rounded-3xl
                    bg-miko-cream dark:bg-miko-rust/10
                    border border-miko-carrot/30 dark:border-miko-rust/30
                    transition-all
                    hover:bg-miko-carrot/15 dark:hover:bg-miko-rust/20
                  "
                >
                  <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-miko-rust to-miko-pumpkin flex items-center justify-center text-white shadow-miko flex-shrink-0">
                    <SiteImage
                      imageKey="icon_cart"
                      showPlaceholder
                      placeholderContent={<span className="text-xl" aria-hidden="true">🛒</span>}
                      className="w-6 h-6 object-contain"
                    />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="font-black text-miko-rust dark:text-miko-cream text-[14px]">
                      سبد خرید
                    </div>
                    <div className="text-[12px] text-miko-rust/80 dark:text-miko-carrot/80 mt-0.5">
                      {toFa(cart.totalCount)} سفارش منتظر پرداخت
                    </div>
                  </div>
                  <SiteImage
                    imageKey="icon_arrow_left"
                    showPlaceholder={true}
                    placeholderContent={<span className="text-miko-carrot text-sm">←</span>}
                    className="w-4 h-4 object-contain flex-shrink-0"
                  />
                </Link>
              </nav>
            )}

            <nav className="px-3 sm:px-4 pt-4 pb-3" aria-label="بخش‌های صفحه">
              <div className="text-[10px] font-bold text-miko-rust dark:text-miko-carrot uppercase tracking-[0.15em] px-3 sm:px-4 py-2 flex items-center gap-2">
                <SiteImage
                  imageKey="icon_location"
                  showPlaceholder={true}
                  placeholderContent={<span>📍</span>}
                  className="w-3.5 h-3.5 object-contain"
                />
                <span>بخش‌های صفحه</span>
              </div>
              {SECTIONS.map((item) => (
                <button
                  key={item.hash}
                  type="button"
                  onClick={() => handleSectionClick(item.hash)}
                  className="
                    w-full text-right
                    flex items-center gap-3 sm:gap-4
                    px-3 sm:px-4 py-3.5 min-h-[52px]
                    rounded-2xl
                    text-[14px] font-medium
                    text-miko-dark dark:text-miko-cream
                    hover:bg-miko-carrot/10 dark:hover:bg-miko-rust/15
                    transition
                  "
                >
                  <div className="w-5 text-center text-base flex-shrink-0 flex items-center justify-center">
                    <SiteImage
                      imageKey={item.iconKey}
                      showPlaceholder={true}
                      placeholderContent={<span>{item.fallbackIcon}</span>}
                      className="w-5 h-5 object-contain"
                    />
                  </div>
                  <span className="flex-1 truncate">{item.label}</span>
                  <SiteImage
                    imageKey="icon_arrow_left"
                    showPlaceholder={true}
                    placeholderContent={<span className="text-miko-carrot text-xs">←</span>}
                    className="w-3.5 h-3.5 object-contain flex-shrink-0"
                  />
                </button>
              ))}
            </nav>

            {isLoggedIn && (
              <nav
                className="px-3 sm:px-4 pb-3 border-t border-miko-carrot/20 dark:border-dark-700 pt-4 mt-2"
                aria-label="منوی حساب کاربری"
              >
                <div className="text-[10px] font-bold text-miko-rust dark:text-miko-carrot uppercase tracking-[0.15em] px-3 sm:px-4 py-2 flex items-center gap-2">
                  <SiteImage
                    imageKey="icon_user"
                    showPlaceholder={true}
                    placeholderContent={<span>👤</span>}
                    className="w-3.5 h-3.5 object-contain"
                  />
                  <span>حساب کاربری</span>
                </div>
                {USER_MENU_ITEMS.map((item) => (
                  <Link
                    key={item.href}
                    to={item.href}
                    onClick={() => setSidebarOpen(false)}
                    className="
                      flex items-center gap-3 sm:gap-4
                      px-3 sm:px-4 py-3.5 min-h-[52px]
                      rounded-2xl
                      text-[14px] font-medium
                      text-miko-dark dark:text-miko-cream
                      hover:bg-miko-carrot/10 dark:hover:bg-miko-rust/15
                      transition
                    "
                  >
                    <div className="w-5 text-center text-base flex-shrink-0 flex items-center justify-center">
                      <SiteImage
                        imageKey={item.iconKey}
                        showPlaceholder={true}
                        placeholderContent={<span>{item.fallbackIcon}</span>}
                        className="w-5 h-5 object-contain"
                      />
                    </div>
                    <span className="flex-1 truncate">{item.label}</span>
                    <SiteImage
                      imageKey="icon_arrow_left"
                      showPlaceholder={true}
                      placeholderContent={<span className="text-miko-carrot text-xs">←</span>}
                      className="w-3.5 h-3.5 object-contain flex-shrink-0"
                    />
                  </Link>
                ))}
              </nav>
            )}
          </div>

          <div className="p-4 sm:p-5 border-t border-miko-carrot/20 dark:border-dark-700 flex-shrink-0 bg-miko-carrot/5 dark:bg-ink-950/50">
            {isLoggedIn ? (
              <button
                type="button"
                onClick={() => setShowLogoutConfirm(true)}
                className="
                  w-full min-h-[52px]
                  flex items-center justify-center gap-3
                  px-5 py-3.5
                  bg-rose-50 dark:bg-rose-500/10
                  hover:bg-rose-100 dark:hover:bg-rose-500/20
                  text-rose-600 dark:text-rose-400
                  border border-rose-200 dark:border-rose-500/30
                  rounded-2xl text-[14px] font-bold transition
                "
              >
                <SiteImage
                  imageKey="icon_logout"
                  showPlaceholder={true}
                  placeholderContent={<span aria-hidden="true">🚪</span>}
                  className="w-4 h-4 object-contain"
                />
                <span>خروج از حساب</span>
              </button>
            ) : (
              <div className="grid grid-cols-2 gap-3">
                <Link
                  to="/login"
                  onClick={() => setSidebarOpen(false)}
                  className="
                    min-h-[52px] flex items-center justify-center
                    px-5 py-3.5
                    bg-white dark:bg-ink-800
                    hover:bg-miko-carrot/10 dark:hover:bg-ink-700
                    text-miko-olive dark:text-miko-carrot
                    border border-miko-carrot/30 dark:border-dark-700
                    rounded-2xl text-[14px] font-bold transition
                  "
                >
                  ورود
                </Link>
                <Link
                  to="/register"
                  onClick={() => setSidebarOpen(false)}
                  className="
                    min-h-[52px] flex items-center justify-center
                    px-5 py-3.5
                    bg-gradient-to-br from-miko-rust to-miko-pumpkin text-white
                    rounded-2xl text-[14px] font-bold
                    transition shadow-miko
                  "
                >
                  ثبت‌نام
                </Link>
              </div>
            )}
          </div>
        </aside>
      </div>

      {/* Logout Confirmation */}
      {showLogoutConfirm && (
        <div
          className="fixed inset-0 bg-ink-900/70 backdrop-blur-sm flex items-center justify-center z-[70] p-4 sm:p-5 animate-fadeIn"
          role="dialog"
          aria-modal="true"
          aria-labelledby="logout-modal-title"
        >
          <div className="bg-miko-cream dark:bg-ink-800 rounded-3xl shadow-editorial w-full max-w-sm p-5 sm:p-6 border border-miko-carrot/30 dark:border-dark-700 animate-fade-down">
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-rose-100 dark:bg-rose-500/20 rounded-3xl flex items-center justify-center mx-auto mb-4">
                <SiteImage
                  imageKey="icon_logout"
                  showPlaceholder={true}
                  placeholderContent={<span className="text-3xl" aria-hidden="true">🚪</span>}
                  className="w-8 h-8 object-contain"
                />
              </div>
              <h3
                id="logout-modal-title"
                className="font-display font-black text-xl text-miko-dark dark:text-miko-cream mb-3"
              >
                خروج از حساب
              </h3>
              <p className="text-[14px] text-miko-dark/70 dark:text-miko-cream/80 leading-relaxed">
                آیا مطمئن هستی که می‌خواهی از حسابت خارج شوی؟
              </p>
            </div>
            <div className="flex flex-col sm:flex-row gap-3">
              <button
                type="button"
                onClick={() => setShowLogoutConfirm(false)}
                className="flex-1 min-h-[52px] bg-miko-carrot/10 dark:bg-ink-700 hover:bg-miko-carrot/20 dark:hover:bg-ink-600 text-miko-dark dark:text-miko-cream px-5 py-3.5 rounded-2xl font-bold text-[14px] transition"
              >
                انصراف
              </button>
              <button
                type="button"
                onClick={handleLogout}
                className="flex-1 min-h-[52px] bg-rose-500 hover:bg-rose-600 active:bg-rose-700 text-white px-5 py-3.5 rounded-2xl font-bold text-[14px] transition shadow-sm"
              >
                خروج
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}