import React, { useEffect, useState, useCallback, useRef } from 'react';
import { SiteImage } from '../../utils/SiteImage';

// ============================================================
//  🎨 Types: 'success' | 'error' | 'info' | 'warning'
//  هر نوع یه strip رنگی + آیکون badge + عنوان داره
//  Editorial palette: accent / rose / brand / ink
// ============================================================
const TOAST_CONFIG = {
  success: {
    icon: '✓', iconKey: 'icon_check',
    label: 'موفق',
    strip: 'bg-accent-500',
    iconBg:
      'bg-accent-100 dark:bg-accent-500/25 text-accent-700 dark:text-accent-300',
    titleColor: 'text-accent-800 dark:text-accent-200',
    border: 'border-accent-200 dark:border-accent-500/30',
  },
  error: {
    icon: '!',
    label: 'خطا',
    strip: 'bg-rose-500',
    iconBg:
      'bg-rose-100 dark:bg-rose-500/25 text-rose-700 dark:text-rose-300',
    titleColor: 'text-rose-800 dark:text-rose-200',
    border: 'border-rose-200 dark:border-rose-500/30',
  },
  warning: {
    icon: '⚠', iconKey: 'icon_warning',
    label: 'هشدار',
    strip: 'bg-brand-500',
    iconBg:
      'bg-brand-100 dark:bg-brand-500/25 text-brand-700 dark:text-brand-300',
    titleColor: 'text-brand-800 dark:text-brand-200',
    border: 'border-brand-200 dark:border-brand-500/30',
  },
  info: {
    icon: 'ℹ', iconKey: 'icon_info',
    label: 'اطلاع',
    strip: 'bg-ink-500',
    iconBg: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200',
    titleColor: 'text-ink-800 dark:text-cream-100',
    border: 'border-ink-200 dark:border-dark-600',
  },
};

// ============================================================
//  ✅ MOBILE: موقعیت Toast بر اساس prop
//  - 'default': پایین صفحه (مناسب ادمین)
//  - 'above-nav': بالای bottom nav (مناسب کاربر موبایل)
// ============================================================
const POSITION_CLASSES = {
  default: 'bottom-4 sm:bottom-6',
  'above-nav': 'bottom-20 sm:bottom-6',
};

// ============================================================
//  🔑 تولید شناسهٔ یکتا — crypto if available, fallback otherwise
// ============================================================
const generateId = () => {
  if (
    typeof crypto !== 'undefined' &&
    typeof crypto.randomUUID === 'function'
  ) {
    return crypto.randomUUID();
  }
  return `${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2, 10)}`;
};

// ============================================================
//  🎨 ToastView — Editorial Style
//  - کارت کاغذی با border ظریف
//  - نوار رنگی سمت راست بر اساس نوع
//  - آیکون در badge دایره‌ای
//  - عناوین با font-display
//  - انیمیشن slide-up نرم
//  - role="alert" برای error، role="status" برای بقیه
//  - closeOnAction: بستن خودکار هنگام کلیک روی action
// ============================================================
export function ToastView({
  type = 'info',
  message,
  onClose,
  action,
  offset = 'default',
  closeOnAction = true,
}) {
  const cfg = TOAST_CONFIG[type] || TOAST_CONFIG.info;
  const positionClass =
    POSITION_CLASSES[offset] || POSITION_CLASSES.default;
  const role = type === 'error' ? 'alert' : 'status';

  const handleActionClick = () => {
    try {
      action?.onClick?.();
    } finally {
      if (closeOnAction) onClose?.();
    }
  };

  return (
    <div
      className={`
        fixed left-1/2 -translate-x-1/2 z-[70]
        ${positionClass}
        w-[calc(100%-2rem)] sm:w-auto sm:max-w-md
        bg-paper-50 dark:bg-ink-800
        border ${cfg.border}
        rounded-2xl
        shadow-editorial
        overflow-hidden
        animate-slide-up
        safe-bottom
        noise-overlay
      `}
      role={role}
      dir="rtl"
    >
      {/* محتوای Toast — با نوار رنگی سمت راست */}
      <div className="relative flex items-stretch">
        {/* نوار رنگی سمت راست */}
        <div
          className={`w-1.5 ${cfg.strip} flex-shrink-0`}
          aria-hidden="true"
        />

        {/* بدنه */}
        <div className="flex-1 flex items-start gap-3 p-4 sm:p-5 min-w-0">
          {/* آیکون badge */}
          <div
            className={`flex-shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center text-lg font-display font-black ${cfg.iconBg}`}
            aria-hidden="true"
          >
            {cfg.icon}
          </div>

          {/* متن */}
          <div className="flex-1 min-w-0 pt-0.5">
            <div
              className={`font-display font-black text-[10px] tracking-[0.15em] mb-1 ${cfg.titleColor}`}
            >
              {cfg.label}
            </div>
            <div className="text-sm text-ink-800 dark:text-cream-100 leading-relaxed break-safe font-bold">
              {message}
            </div>

            {/* دکمهٔ اکشن — زیر متن */}
            {action && (
              <button
                type="button"
                onClick={handleActionClick}
                className="mt-3 min-h-[36px] inline-flex items-center gap-1.5 px-3.5 py-1.5 bg-ink-900 dark:bg-cream-100 text-cream-50 dark:text-ink-900 hover:opacity-90 active:opacity-80 rounded-xl text-xs font-black transition-all touch-target"
                title={action.label}
              >
                <span>{action.label}</span>
                <SiteImage imageKey="icon_arrow_left" fallback="←" alt="" className="leading-none inline-flex" />
              </button>
            )}
          </div>

          {/* دکمهٔ بستن */}
          {onClose && (
            <button
              type="button"
              onClick={onClose}
              className="flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-xl text-ink-400 dark:text-cream-400 hover:text-ink-700 dark:hover:text-cream-100 hover:bg-ink-100 dark:hover:bg-ink-700/60 active:bg-ink-200 dark:active:bg-ink-700 transition text-base touch-target"
              title="بستن"
              aria-label="بستن اعلان"
            >
              ✕
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// ============================================================
//  Hook: useToast
//  ✅ پشتیبانی از صف Toast (چند پیام پشت سر هم)
//  ✅ hideAll برای بستن دسته‌جمعی
//
//  استفاده:
//    const { toast, showToast, hideToast, hideAll } = useToast();
//    showToast('success', 'ذخیره شد!');
//    showToast('error', 'خطا', { duration: 5000 });
//    showToast('info', 'آیا مطمئنید؟', {
//      action: { label: 'بله', onClick: () => doIt() },
//      closeOnAction: true,
//    });
//    // در JSX: {toast && <ToastView {...toast} onClose={hideToast} />}
// ============================================================
export function useToast(defaultDuration = 3000) {
  const [toast, setToast] = useState(null);
  const queueRef = useRef([]);

  // ===== Auto-hide با timeout + پردازش صف =====
  useEffect(() => {
    if (!toast) {
      // اگه صف خالیه، هیچ کاری نکن
      if (queueRef.current.length === 0) return;

      // در غیر این صورت، از صف بعدی رو نشون بده
      const next = queueRef.current.shift();
      setToast(next);
      return;
    }

    const duration = toast.duration ?? defaultDuration;
    if (duration <= 0) return; // اگه duration صفر بود، خودکار بسته نشه

    const timer = setTimeout(() => setToast(null), duration);
    return () => clearTimeout(timer);
  }, [toast, defaultDuration]);

  const showToast = useCallback((type, message, options = {}) => {
    const newToast = {
      type,
      message,
      duration: options.duration,
      action: options.action,
      closeOnAction: options.closeOnAction,
      id: generateId(),
    };

    setToast((prev) => {
      // اگه Toast فعلی در حال نمایشه، به صف اضافه کن
      if (prev) {
        queueRef.current.push(newToast);
        return prev;
      }
      // در غیر این صورت، مستقیم نشون بده
      return newToast;
    });
  }, []);

  const hideToast = useCallback(() => {
    setToast(null);
  }, []);

  const hideAll = useCallback(() => {
    queueRef.current = [];
    setToast(null);
  }, []);

  return { toast, showToast, hideToast, hideAll };
}

// ============================================================
//  Global Toast Host (singleton)
//  ✅ MOBILE: prop جدید offset برای موقعیت‌یابی هوشمند
//
//  استفاده:
//    // در پنل ادمین (بدون bottom nav):
//    <ToastHost />
//    // در پنل کاربر (با bottom nav روی موبایل):
//    <ToastHost offset="above-nav" />
// ============================================================
let globalToastFn = null;

export function ToastHost({ offset = 'default' }) {
  const { toast, showToast, hideToast } = useToast();

  useEffect(() => {
    globalToastFn = {
      success: (msg, opts) => showToast('success', msg, opts),
      error: (msg, opts) => showToast('error', msg, opts),
      info: (msg, opts) => showToast('info', msg, opts),
      warning: (msg, opts) => showToast('warning', msg, opts),
    };
    return () => {
      globalToastFn = null;
    };
  }, [showToast]);

  if (!toast) return null;

  return (
    <ToastView
      key={toast.id}
      {...toast}
      onClose={hideToast}
      offset={offset}
    />
  );
}

// ============================================================
//  Global API (اختیاری)
//  اگه ToastHost توی ریشه اپ نصب شده باشه، از هرجا می‌تونی صدا بزنی:
//    toast.success('ذخیره شد');
//    toast.error('خطای شبکه');
// ============================================================
export const toast = {
  success: (msg, opts) => globalToastFn?.success(msg, opts),
  error: (msg, opts) => globalToastFn?.error(msg, opts),
  info: (msg, opts) => globalToastFn?.info(msg, opts),
  warning: (msg, opts) => globalToastFn?.warning(msg, opts),
};

// ============================================================
//  Export پیش‌فرض برای سادگی
// ============================================================
export default ToastView;

