// frontend/src/user/components/QuickCalculator.jsx
// ============================================================
//  🐾 QuickCalculator v5.1 — Miko Warm Palette
//  ✅ آیکون‌های باقی‌ماندهٔ هاردکد (✓ ▼ ↻ ←) به SiteImage منتقل شدند
// ============================================================

import React, { useState, useCallback, useEffect, useRef } from 'react';
import publicAxios from '../publicAxios';
import userAxios from '../userAxios';
import {
  toFa,
  toFaDecimal,
  toFaDigits,
  toFaNumberInput,
  toEnDigits,
} from '../../utils/numbers';
import { SiteImage } from '../../utils/SiteImage';
import {
  STORAGE_KEYS,
  SESSION_KEYS,
  AUTH_EVENT,
  USER_DATA_EVENT,
} from '../../constants/storageKeys';

const DEBUG = process.env.NODE_ENV !== 'production';
const logDebug = (...args) => {
  if (DEBUG) console.warn(...args);
};

const DEFAULT_FULL_FORM = {
  breed: 'medium',
  temperature: 'moderate',
  is_neutered: false,
  activity: 'moderate',
  bcs: 'ideal',
  pregnancy: 'no',
  disease: 'healthy',
  stress: 'low',
  surgery: 'no_surgery',
  allergy_type: 'none',
  allergy_details: '',
  allergens: [],
  days_count: 7,
  phone: '',
  email: '',
};

const DEFAULT_FORM = {
  dog_name: '',
  weight_kg: '',
  age_years: '',
  age_months_extra: '',
};

const MIN_WEIGHT = 1;
const MAX_WEIGHT = 120;
const MAX_AGE_MONTHS = 360;

const NUMERIC_FIELDS = ['weight_kg', 'age_years', 'age_months_extra'];

// ============================================================
//  ✅ usePrefersReducedMotion (reactive)
// ============================================================
function usePrefersReducedMotion() {
  const [prefers, setPrefers] = useState(() => {
    if (typeof window === 'undefined') return false;
    return (
      window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches || false
    );
  });

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const mq = window.matchMedia?.('(prefers-reduced-motion: reduce)');
    if (!mq) return;
    const handler = (e) => setPrefers(e.matches);
    if (mq.addEventListener) mq.addEventListener('change', handler);
    else if (mq.addListener) mq.addListener(handler);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener('change', handler);
      else if (mq.removeListener) mq.removeListener(handler);
    };
  }, []);

  return prefers;
}

function Field({ id, label, helper, icon, iconKey, children, error }) {
  return (
    <div className="min-w-0">
      <label
        htmlFor={id}
        className="mb-2 flex items-center gap-2 text-sm font-extrabold text-miko-dark dark:text-cream-200"
      >
        <span
          className="flex h-8 w-8 items-center justify-center rounded-xl bg-miko-carrot/15 dark:bg-miko-rust/15 p-1.5 flex-shrink-0"
          aria-hidden="true"
        >
          {iconKey ? (
            <SiteImage
              imageKey={iconKey}
              fallback={icon}
              alt=""
              className="w-full h-full object-contain"
            />
          ) : (
            <span className="text-lg">{icon}</span>
          )}
        </span>
        <span className="min-w-0">{label}</span>
      </label>
      {children}
      {error ? (
        <p
          role="alert"
          className="mt-1.5 text-xs font-semibold text-rose-600 dark:text-rose-400"
        >
          {error}
        </p>
      ) : helper ? (
        <p className="mt-1.5 text-xs leading-5 text-miko-dark/60 dark:text-cream-400">
          {helper}
        </p>
      ) : null}
    </div>
  );
}

function ResultCard({ icon, iconKey, label, value, unit, featured = false, helper }) {
  return (
    <div
      className={`rounded-2xl border p-3 min-w-0 ${
        featured
          ? 'border-miko-carrot bg-miko-carrot/10 dark:border-miko-rust/40 dark:bg-miko-rust/15'
          : 'border-miko-carrot/25 bg-white/70 dark:border-dark-700 dark:bg-ink-900/40'
      }`}
    >
      <div className="mb-1.5 flex items-center gap-1.5 text-[11px] sm:text-xs font-bold text-miko-dark/60 dark:text-cream-400 min-w-0">
        {iconKey ? (
          <SiteImage
            imageKey={iconKey}
            fallback={icon}
            alt=""
            className="w-4 h-4 object-contain flex-shrink-0"
          />
        ) : (
          <span aria-hidden="true" className="text-base flex-shrink-0">
            {icon}
          </span>
        )}
        <span className="truncate">{label}</span>
      </div>
      <div
        className={`break-words text-lg sm:text-xl font-black leading-tight font-num ${
          featured
            ? 'text-miko-rust dark:text-miko-carrot'
            : 'text-miko-dark dark:text-cream-100'
        }`}
      >
        {value ?? '—'}
        <span className="mr-1.5 text-[11px] sm:text-xs font-bold text-miko-dark/60 dark:text-cream-400">
          {unit}
        </span>
      </div>
      {helper && (
        <p className="mt-1 text-[11px] leading-4 text-miko-dark/60 dark:text-cream-400">
          {helper}
        </p>
      )}
    </div>
  );
}

export default function QuickCalculator({ onCalculated }) {
  const [view, setView] = useState('form');
  const [form, setForm] = useState({ ...DEFAULT_FORM });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState(null);
  const [touched, setTouched] = useState({});
  const isMountedRef = useRef(true);

  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [dogs, setDogs] = useState([]);
  const [dogsLoading, setDogsLoading] = useState(false);
  const [selectedDogId, setSelectedDogId] = useState('');
  const [pickerOpen, setPickerOpen] = useState(false);

  const pickerRef = useRef(null);

  const prefersReducedMotion = usePrefersReducedMotion();

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  // ============================================================
  //  🔐 همگام‌سازی وضعیت لاگین
  // ============================================================
  useEffect(() => {
    const syncAuth = () => {
      try {
        setIsLoggedIn(!!localStorage.getItem(STORAGE_KEYS.USER_TOKEN));
      } catch {
        setIsLoggedIn(false);
      }
    };
    syncAuth();
    window.addEventListener('storage', syncAuth);
    window.addEventListener(AUTH_EVENT, syncAuth);
    window.addEventListener(USER_DATA_EVENT, syncAuth);
    return () => {
      window.removeEventListener('storage', syncAuth);
      window.removeEventListener(AUTH_EVENT, syncAuth);
      window.removeEventListener(USER_DATA_EVENT, syncAuth);
    };
  }, []);

  // ============================================================
  //  🐕 دریافت سگ‌های ثبت‌شده
  // ============================================================
  const fetchDogs = useCallback(() => {
    if (!isLoggedIn) {
      setDogs([]);
      setDogsLoading(false);
      return;
    }
    setDogsLoading(true);
    userAxios
      .get('/api/dogs')
      .then((res) => {
        if (!isMountedRef.current) return;
        setDogs(Array.isArray(res.data) ? res.data : []);
      })
      .catch((err) => {
        if (!isMountedRef.current) return;
        logDebug('fetchDogs error:', err?.response?.data?.detail || err.message);
        setDogs([]);
      })
      .finally(() => {
        if (isMountedRef.current) setDogsLoading(false);
      });
  }, [isLoggedIn]);

  useEffect(() => {
    fetchDogs();
  }, [fetchDogs]);

  // ============================================================
  //  🎯 بستن picker با کلیک بیرون / Escape
  // ============================================================
  useEffect(() => {
    if (!pickerOpen) return;

    const handleClickOutside = (e) => {
      if (pickerRef.current && !pickerRef.current.contains(e.target)) {
        setPickerOpen(false);
      }
    };

    const handleEsc = (e) => {
      if (e.key === 'Escape') setPickerOpen(false);
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('touchstart', handleClickOutside);
    document.addEventListener('keydown', handleEsc);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('touchstart', handleClickOutside);
      document.removeEventListener('keydown', handleEsc);
    };
  }, [pickerOpen]);

  // ============================================================
  //  🎯 انتخاب سگ
  // ============================================================
  const handleSelectDog = useCallback((dog) => {
    setSelectedDogId(String(dog.id));

    const totalMonths = Number(dog.age_months) || 0;
    const years = Math.floor(totalMonths / 12);
    const months = totalMonths % 12;

    setForm({
      dog_name: dog.name || '',
      weight_kg:
        dog.weight_kg != null ? toFaNumberInput(String(dog.weight_kg)) : '',
      age_years: years > 0 ? toFaDigits(String(years)) : '',
      age_months_extra: months > 0 ? toFaDigits(String(months)) : '',
    });
    setTouched({});
    setError('');
    setPickerOpen(false);
  }, []);

  const handleDeselectDog = useCallback((e) => {
    if (e) {
      e.stopPropagation();
      e.preventDefault();
    }
    setSelectedDogId('');
    setForm({ ...DEFAULT_FORM });
    setTouched({});
    setError('');
    setPickerOpen(false);
  }, []);

  // ============================================================
  //  ✅ handleChange
  // ============================================================
  const handleChange = (e) => {
    const { name, value } = e.target;

    let newValue = value;
    if (NUMERIC_FIELDS.includes(name)) {
      newValue =
        name === 'weight_kg'
          ? toFaNumberInput(value)
          : toFaDigits(value);
    }

    setForm((prev) => ({ ...prev, [name]: newValue }));
    setError('');
    if (selectedDogId) setSelectedDogId('');
  };

  const handleBlur = (e) => {
    setTouched((prev) => ({ ...prev, [e.target.name]: true }));
  };

  // ============================================================
  //  ✅ مقادیر مشتق‌شده
  // ============================================================
  const weight = toEnDigits(form.weight_kg);
  const years = toEnDigits(form.age_years);
  const extraMonths = toEnDigits(form.age_months_extra);
  const parsedYears = years === '' ? 0 : Number(years);
  const parsedExtraMonths = extraMonths === '' ? 0 : Number(extraMonths);
  const totalAgeMonths = parsedYears * 12 + parsedExtraMonths;

  const validation = {
    dog_name: form.dog_name.trim().length >= 1,
    weight_kg:
      weight !== '' &&
      !Number.isNaN(Number(weight)) &&
      Number(weight) >= MIN_WEIGHT &&
      Number(weight) <= MAX_WEIGHT,
    age:
      (years !== '' || extraMonths !== '') &&
      Number.isInteger(parsedYears) &&
      parsedYears >= 0 &&
      Number.isInteger(parsedExtraMonths) &&
      parsedExtraMonths >= 0 &&
      parsedExtraMonths <= 11 &&
      totalAgeMonths <= MAX_AGE_MONTHS,
  };
  const isValid = validation.dog_name && validation.weight_kg && validation.age;

  // ============================================================
  //  Submit
  // ============================================================
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!isValid) {
      setTouched({
        dog_name: true,
        weight_kg: true,
        age_years: true,
        age_months_extra: true,
      });
      const errors = [];
      if (!validation.dog_name) errors.push('نام سگ');
      if (!validation.weight_kg)
        errors.push(`وزن بین ${toFa(MIN_WEIGHT)} تا ${toFa(MAX_WEIGHT)} کیلوگرم`);
      if (!validation.age)
        errors.push('سن به‌صورت سال و ماه (ماه باید بین ۰ تا ۱۱ باشد)');
      setError(`لطفاً این موارد را بررسی کن: ${errors.join('، ')}.`);
      return;
    }

    setLoading(true);
    setError('');
    try {
      const selectedDog = selectedDogId
        ? dogs.find((d) => String(d.id) === String(selectedDogId))
        : null;

      const payload = {
        ...DEFAULT_FULL_FORM,
        dog_name: form.dog_name.trim(),
        weight_kg: Number(weight),
        age_months: totalAgeMonths,
        allergens: [],
      };

      if (selectedDog) {
        payload.dog_id = selectedDog.id;

        if (selectedDog.breed) payload.breed = selectedDog.breed;
        if (selectedDog.bcs) payload.bcs = selectedDog.bcs;
        if (selectedDog.disease) payload.disease = selectedDog.disease;
        if (typeof selectedDog.is_neutered === 'boolean') {
          payload.is_neutered = selectedDog.is_neutered;
        }
        if (selectedDog.activity) payload.activity = selectedDog.activity;
        if (selectedDog.pregnancy) payload.pregnancy = selectedDog.pregnancy;
        if (selectedDog.surgery) payload.surgery = selectedDog.surgery;
        if (selectedDog.temperature) payload.temperature = selectedDog.temperature;
        if (selectedDog.stress) payload.stress = selectedDog.stress;

        const dogAllergens = Array.isArray(selectedDog.allergens)
          ? selectedDog.allergens
          : [];
        if (dogAllergens.length > 0) {
          payload.allergens = dogAllergens;
        }
      }

      const res = await publicAxios.post('/api/calculate-order', payload);
      if (!isMountedRef.current) return;

      setResult(res.data);
      try {
        sessionStorage.setItem(SESSION_KEYS.QUICK_RESULT, JSON.stringify(res.data));
        sessionStorage.setItem(SESSION_KEYS.QUICK_FORM, JSON.stringify(payload));

        if (!selectedDog) {
          sessionStorage.setItem(
            SESSION_KEYS.PENDING_DOG,
            JSON.stringify({
              dog_name: payload.dog_name,
              name: payload.dog_name,
              weight_kg: payload.weight_kg,
              age_months: payload.age_months,
              breed: payload.breed,
              is_neutered: payload.is_neutered,
              bcs: payload.bcs,
              disease: payload.disease,
              allergens: payload.allergens || [],
              activity: payload.activity,
              pregnancy: payload.pregnancy,
              surgery: payload.surgery,
              temperature: payload.temperature,
              stress: payload.stress,
            })
          );
        } else {
          sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
        }
      } catch (storageErr) {
        logDebug('sessionStorage error:', storageErr);
      }

      if (typeof onCalculated === 'function') onCalculated(res.data, payload);
      setView('result');
    } catch (err) {
      if (!isMountedRef.current) return;
      logDebug('Error in calculate-order:', err);
      const detail = err.response?.data?.detail;
      let msg =
        'نتوانستیم اطلاعات را محاسبه کنیم. لطفاً اتصال اینترنت را بررسی کن و دوباره تلاش کن.';
      if (Array.isArray(detail)) {
        msg = detail.map((d) => `${d.loc?.join('.')}: ${d.msg}`).join(' | ');
      } else if (typeof detail === 'string') {
        msg = detail;
      } else if (err.message) {
        msg =
          'ارتباط با سرویس محاسبه برقرار نشد. لطفاً چند لحظه بعد دوباره تلاش کن.';
      }
      setError(msg);
    } finally {
      if (isMountedRef.current) setLoading(false);
    }
  };

  const handleContinue = useCallback(() => {
    const el = document.getElementById('order-form-section');
    if (!el) return;
    const headerOffset = 80;
    const top =
      el.getBoundingClientRect().top + window.pageYOffset - headerOffset;
    window.scrollTo({
      top,
      behavior: prefersReducedMotion ? 'auto' : 'smooth',
    });
  }, [prefersReducedMotion]);

  const handleEdit = () => {
    setError('');
    setView('form');
  };

  const handleReset = () => {
    setResult(null);
    setForm({ ...DEFAULT_FORM });
    setTouched({});
    setError('');
    setSelectedDogId('');
    setPickerOpen(false);
    setView('form');
    try {
      sessionStorage.removeItem(SESSION_KEYS.QUICK_RESULT);
      sessionStorage.removeItem(SESSION_KEYS.QUICK_FORM);
      sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
    } catch (storageErr) {
      logDebug('sessionStorage cleanup error:', storageErr);
    }
    if (typeof onCalculated === 'function') onCalculated(null, null);
  };

  const totalAgeLabel = (() => {
    if (!result) return '';
    const months = Number(result?.age_months ?? totalAgeMonths);
    if (!Number.isFinite(months)) return '';
    const y = Math.floor(months / 12);
    const m = months % 12;
    if (y && m) return `${toFa(y)} سال و ${toFa(m)} ماه`;
    if (y) return `${toFa(y)} سال`;
    return `${toFa(m)} ماه`;
  })();

  const hasSavedDogs = isLoggedIn && !dogsLoading && dogs.length > 0;
  const selectedDog = selectedDogId
    ? dogs.find((d) => String(d.id) === String(selectedDogId))
    : null;

  return (
    <section
      className="relative mx-auto w-full max-w-2xl px-2 sm:px-0"
      dir="rtl"
      aria-label="محاسبه مقدار غذا و هزینه"
    >
      <div
        className="pointer-events-none absolute -inset-3 rounded-[2rem] bg-miko-carrot/8 blur-2xl"
        aria-hidden="true"
      />
      <div className="relative overflow-hidden rounded-3xl border border-miko-carrot/30 bg-miko-cream shadow-editorial dark:border-dark-700 dark:bg-ink-800">
        {/* نوار گرادیانت میکو بالای کارت */}
        <div
          className="h-1.5 bg-gradient-to-r from-miko-rust via-miko-pumpkin to-miko-carrot"
          aria-hidden="true"
        />

        <div className="grid min-h-[460px]">
          {/* ============================================================ */}
          {/*  نمای فرم                                                    */}
          {/* ============================================================ */}
          <div
            className={`col-start-1 row-start-1 flex flex-col p-4 sm:p-6 lg:p-7 transition-opacity duration-300 ${
              view === 'form' ? 'opacity-100' : 'pointer-events-none opacity-0'
            }`}
            aria-hidden={view !== 'form'}
            {...(view !== 'form' ? { inert: '' } : {})}
          >
            {!isLoggedIn && (
              <div className="mb-5 inline-flex w-fit items-center gap-2 rounded-full border border-miko-olive/30 bg-miko-olive/10 px-3 py-1.5 text-[11px] sm:text-xs font-bold text-miko-olive dark:text-miko-leaf">
                <SiteImage
                  imageKey="icon_sparkles"
                  fallback="✦"
                  alt=""
                  className="w-3.5 h-3.5 object-contain"
                />
                <span>رایگان · بدون ثبت‌نام</span>
              </div>
            )}

            <div className="mb-5 sm:mb-6">
              <h2 className="mb-2 text-xl font-black leading-tight text-miko-dark dark:text-cream-100 sm:text-2xl lg:text-3xl">
                غذای مناسب سگت چقدر هزینه دارد؟
              </h2>
              <p className="text-sm leading-6 text-miko-dark/70 dark:text-cream-300">
                فقط چند مشخصات ساده را وارد کن تا مقدار تقریبی غذای روزانه و
                هزینه بسته را ببینی.
              </p>
            </div>

            <form onSubmit={handleSubmit} noValidate className="flex flex-1 flex-col">
              <div className="space-y-4 sm:space-y-5">
                {/* ============================================================
                    🐕 دکمه‌ی انتخاب سگ
                    ============================================================ */}
                {hasSavedDogs && (
                  <div className="relative" ref={pickerRef}>
                    <button
                      type="button"
                      onClick={() => setPickerOpen((v) => !v)}
                      disabled={loading}
                      aria-haspopup="listbox"
                      aria-expanded={pickerOpen}
                      className={`w-full flex items-center gap-2.5 h-12 px-3.5 rounded-xl border-2 text-right transition-all duration-200 disabled:opacity-60 touch-target ${
                        selectedDog
                          ? 'bg-miko-carrot/10 dark:bg-miko-rust/15 border-miko-carrot dark:border-miko-rust/50'
                          : 'bg-miko-cream dark:bg-ink-800/60 border-miko-carrot/25 dark:border-dark-600 hover:border-miko-carrot dark:hover:border-miko-rust/40 hover:bg-miko-carrot/5 dark:hover:bg-miko-rust/10'
                      }`}
                    >
                      <span
                        className={`w-8 h-8 rounded-xl flex items-center justify-center p-1.5 flex-shrink-0 transition-colors duration-200 ${
                          selectedDog
                            ? 'bg-gradient-to-br from-miko-rust to-miko-pumpkin text-white shadow-miko'
                            : 'bg-miko-carrot/10 dark:bg-miko-rust/15 text-miko-rust dark:text-miko-carrot'
                        }`}
                        aria-hidden="true"
                      >
                        <SiteImage
                          imageKey="icon_dog"
                          fallback="🐕"
                          alt=""
                          className="w-full h-full object-contain"
                        />
                      </span>

                      <span className="flex-1 min-w-0 text-right">
                        {selectedDog ? (
                          <>
                            <span className="block text-xs font-black text-miko-rust dark:text-miko-carrot truncate">
                              {selectedDog.name}
                            </span>
                            <span className="block text-[10px] font-num text-miko-rust/80 dark:text-miko-carrot/80 mt-0.5 font-bold truncate">
                              {toFa(selectedDog.weight_kg)} کیلوگرم ·{' '}
                              {toFa(selectedDog.age_months)} ماه
                            </span>
                          </>
                        ) : (
                          <>
                            <span className="block text-xs font-black text-miko-dark dark:text-cream-100">
                              انتخاب سگ ثبت‌شده
                            </span>
                            <span className="block text-[10px] text-miko-dark/60 dark:text-cream-400 mt-0.5 font-bold">
                              اطلاعاتش خودکار پر می‌شه
                            </span>
                          </>
                        )}
                      </span>

                      {selectedDog ? (
                        <span
                          className="w-6 h-6 rounded-full bg-miko-rust text-white flex items-center justify-center flex-shrink-0"
                          aria-hidden="true"
                        >
                          <SiteImage
                            imageKey="icon_check"
                            fallback="✓"
                            alt=""
                            className="w-3.5 h-3.5 object-contain"
                          />
                        </span>
                      ) : (
                        <span
                          className={`flex items-center justify-center transition-transform duration-200 flex-shrink-0 ${
                            pickerOpen ? 'rotate-180' : ''
                          }`}
                          aria-hidden="true"
                        >
                          <SiteImage
                            imageKey="icon_arrow_down"
                            fallback="▼"
                            alt=""
                            className="w-3.5 h-3.5 object-contain opacity-60"
                          />
                        </span>
                      )}
                    </button>

                    {pickerOpen && (
                      <div
                        role="listbox"
                        aria-label="سگ‌های ثبت‌شده"
                        className="absolute top-full right-0 left-0 mt-2 bg-miko-cream dark:bg-ink-800 rounded-2xl border-2 border-miko-carrot/40 dark:border-miko-rust/30 shadow-editorial overflow-hidden z-30 animate-fade-down"
                      >
                        <div className="px-3.5 py-2.5 bg-miko-carrot/10 dark:bg-miko-rust/10 border-b border-miko-carrot/30 dark:border-miko-rust/25 flex items-center justify-between gap-2">
                          <div className="flex items-center gap-2 min-w-0">
                            <SiteImage
                              imageKey="icon_dog"
                              fallback="🐕"
                              alt=""
                              className="w-3.5 h-3.5 object-contain"
                            />
                            <span className="text-[11px] font-black text-miko-rust dark:text-miko-carrot">
                              سگ‌های ثبت‌شده
                            </span>
                          </div>
                          {selectedDog && (
                            <button
                              type="button"
                              onClick={handleDeselectDog}
                              className="text-[10px] font-black text-rose-600 dark:text-rose-400 hover:underline underline-offset-4 transition flex-shrink-0"
                            >
                              پاک کردن
                            </button>
                          )}
                        </div>

                        <ul className="max-h-64 overflow-y-auto scrollbar-hide p-1.5 space-y-1">
                          {dogs.map((dog) => {
                            const isSelected =
                              String(dog.id) === String(selectedDogId);
                            return (
                              <li key={dog.id}>
                                <button
                                  type="button"
                                  role="option"
                                  aria-selected={isSelected}
                                  onClick={() => handleSelectDog(dog)}
                                  className={`w-full flex items-center gap-3 p-2.5 rounded-xl text-right transition-all duration-200 ${
                                    isSelected
                                      ? 'bg-miko-carrot/10 dark:bg-miko-rust/15 border-2 border-miko-carrot dark:border-miko-rust/40'
                                      : 'hover:bg-miko-carrot/5 dark:hover:bg-ink-700/60 border-2 border-transparent'
                                  }`}
                                >
                                  <span
                                    className={`w-9 h-9 rounded-xl flex items-center justify-center p-1.5 flex-shrink-0 ${
                                      isSelected
                                        ? 'bg-gradient-to-br from-miko-rust to-miko-pumpkin text-white shadow-miko'
                                        : 'bg-miko-carrot/10 dark:bg-miko-rust/15 text-miko-rust dark:text-miko-carrot'
                                    }`}
                                    aria-hidden="true"
                                  >
                                    <SiteImage
                                      imageKey="icon_dog"
                                      fallback="🐕"
                                      alt=""
                                      className="w-full h-full object-contain"
                                    />
                                  </span>
                                  <div className="flex-1 min-w-0 text-right">
                                    <div
                                      className={`text-xs font-black truncate ${
                                        isSelected
                                          ? 'text-miko-rust dark:text-miko-carrot'
                                          : 'text-miko-dark dark:text-cream-100'
                                      }`}
                                    >
                                      {dog.name}
                                    </div>
                                    <div
                                      className={`text-[10px] font-num mt-0.5 font-bold ${
                                        isSelected
                                          ? 'text-miko-rust/80 dark:text-miko-carrot/80'
                                          : 'text-miko-dark/60 dark:text-cream-400'
                                      }`}
                                    >
                                      {toFa(dog.weight_kg)} کیلوگرم ·{' '}
                                      {toFa(dog.age_months)} ماه
                                    </div>
                                  </div>
                                  {isSelected && (
                                    <span
                                      className="w-5 h-5 rounded-full bg-miko-rust text-white flex items-center justify-center flex-shrink-0"
                                      aria-hidden="true"
                                    >
                                      <SiteImage
                                        imageKey="icon_check"
                                        fallback="✓"
                                        alt=""
                                        className="w-3 h-3 object-contain"
                                      />
                                    </span>
                                  )}
                                </button>
                              </li>
                            );
                          })}
                        </ul>

                        <div className="px-3.5 py-2 bg-miko-carrot/5 dark:bg-ink-900/40 border-t border-miko-carrot/20 dark:border-dark-700/60">
                          <div className="text-[10px] text-miko-dark/60 dark:text-cream-400 flex items-center gap-1.5 leading-relaxed font-bold">
                            <SiteImage
                              imageKey="icon_lightbulb"
                              fallback="💡"
                              alt=""
                              className="w-3.5 h-3.5 object-contain flex-shrink-0"
                            />
                            <span>
                              با انتخاب سگ، اطلاعاتش خودکار پر می‌شه
                            </span>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                )}

                {/* ===== فیلد اسم سگ ===== */}
                <Field
                  id="qc-dog-name"
                  label="اسم سگت چیه؟"
                  icon="🐶"
                  iconKey="icon_dog"
                  helper="برای اینکه نتیجه را با اسم خودش ببینی."
                  error={
                    touched.dog_name && !validation.dog_name
                      ? 'اسم سگ را وارد کن.'
                      : ''
                  }
                >
                  <input
                    id="qc-dog-name"
                    name="dog_name"
                    type="text"
                    value={form.dog_name}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    placeholder="مثلاً کوکو"
                    autoComplete="off"
                    disabled={loading}
                    className="h-12 w-full rounded-xl border border-miko-carrot/30 bg-white px-4 text-sm text-miko-dark outline-none transition focus:border-miko-rust focus:ring-4 focus:ring-miko-rust/10 dark:border-dark-600 dark:bg-ink-900 dark:text-cream-100"
                  />
                </Field>

                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 sm:gap-5">
                  <Field
                    id="qc-weight"
                    label="وزن سگت چقدره؟"
                    icon="⚖️"
                    iconKey="icon_weight"
                    helper="اگر مطمئن نیستی، آخرین وزن ثبت‌شده را وارد کن."
                    error={
                      touched.weight_kg && !validation.weight_kg
                        ? `وزن باید بین ${toFa(MIN_WEIGHT)} تا ${toFa(
                            MAX_WEIGHT
                          )} کیلوگرم باشد.`
                        : ''
                    }
                  >
                    <div className="relative">
                      <input
                        id="qc-weight"
                        name="weight_kg"
                        type="text"
                        inputMode="decimal"
                        value={form.weight_kg}
                        onChange={handleChange}
                        onBlur={handleBlur}
                        placeholder="مثلاً ۱۲"
                        autoComplete="off"
                        disabled={loading}
                        className="h-12 w-full rounded-xl border border-miko-carrot/30 bg-white px-4 pl-16 text-sm text-miko-dark outline-none transition focus:border-miko-rust focus:ring-4 focus:ring-miko-rust/10 dark:border-dark-600 dark:bg-ink-900 dark:text-cream-100"
                      />
                      <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-[11px] sm:text-xs font-bold text-miko-dark/60 dark:text-cream-400">
                        کیلوگرم
                      </span>
                    </div>
                  </Field>

                  <Field
                    id="qc-age-years"
                    label="سن سگت چقدره؟"
                    icon="🎂"
                    iconKey="icon_cake"
                    helper="سن را به سال و ماه وارد کن؛ مثلاً ۲ سال و ۳ ماه."
                    error={
                      touched.age_years && !validation.age
                        ? 'سن را درست وارد کن؛ ماه باید بین ۰ تا ۱۱ باشد.'
                        : ''
                    }
                  >
                    <div className="grid grid-cols-2 gap-2">
                      <div className="relative min-w-0">
                        <input
                          id="qc-age-years"
                          name="age_years"
                          type="text"
                          inputMode="numeric"
                          value={form.age_years}
                          onChange={handleChange}
                          onBlur={handleBlur}
                          placeholder="سال"
                          autoComplete="off"
                          disabled={loading}
                          className="h-12 w-full rounded-xl border border-miko-carrot/30 bg-white px-3 pl-10 text-sm text-miko-dark outline-none transition focus:border-miko-rust focus:ring-4 focus:ring-miko-rust/10 dark:border-dark-600 dark:bg-ink-900 dark:text-cream-100"
                        />
                        <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[11px] sm:text-xs text-miko-dark/60 dark:text-cream-400">
                          سال
                        </span>
                      </div>
                      <div className="relative min-w-0">
                        <input
                          id="qc-age-months"
                          name="age_months_extra"
                          type="text"
                          inputMode="numeric"
                          value={form.age_months_extra}
                          onChange={handleChange}
                          onBlur={handleBlur}
                          placeholder="ماه"
                          autoComplete="off"
                          disabled={loading}
                          className="h-12 w-full rounded-xl border border-miko-carrot/30 bg-white px-3 pl-10 text-sm text-miko-dark outline-none transition focus:border-miko-rust focus:ring-4 focus:ring-miko-rust/10 dark:border-dark-600 dark:bg-ink-900 dark:text-cream-100"
                        />
                        <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[11px] sm:text-xs text-miko-dark/60 dark:text-cream-400">
                          ماه
                        </span>
                      </div>
                    </div>
                  </Field>
                </div>
              </div>

              {error && (
                <div
                  role="alert"
                  className="mt-4 flex items-start gap-2 rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm leading-6 text-rose-700 dark:border-rose-500/30 dark:bg-rose-500/10 dark:text-rose-200"
                >
                  <SiteImage
                    imageKey="icon_warning"
                    fallback="⚠️"
                    alt=""
                    className="w-4 h-4 object-contain flex-shrink-0 mt-1"
                  />
                  <span className="break-words min-w-0">{error}</span>
                </div>
              )}

              <div className="mt-auto pt-6">
                <button
                  type="submit"
                  disabled={loading}
                  className="flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-br from-miko-rust to-miko-pumpkin px-4 py-3 text-sm font-black text-white shadow-miko transition hover:brightness-105 disabled:cursor-not-allowed disabled:opacity-60 touch-target"
                >
                  {loading ? (
                    <>
                      <span className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" />
                      <span className="truncate">داریم حساب می‌کنیم…</span>
                    </>
                  ) : (
                    <>
                      <SiteImage
                        imageKey="icon_sparkles"
                        fallback="✨"
                        alt=""
                        className="w-4 h-4 object-contain flex-shrink-0"
                      />
                      <span className="truncate">مقدار غذا و قیمت را ببین</span>
                      <SiteImage
                        imageKey="icon_arrow_left"
                        fallback="←"
                        alt=""
                        className="w-4 h-4 object-contain flex-shrink-0"
                      />
                    </>
                  )}
                </button>
                <p className="mt-3 text-center text-[11px] sm:text-xs leading-5 text-miko-dark/60 dark:text-cream-400">
                  در این مرحله نیازی به ثبت‌نام یا وارد کردن شماره تماس نیست.
                </p>
              </div>
            </form>
          </div>

          {/* ============================================================ */}
          {/*  نمای نتیجه                                                  */}
          {/* ============================================================ */}
          <div
            className={`col-start-1 row-start-1 flex flex-col p-4 sm:p-6 lg:p-7 transition-opacity duration-300 ${
              view === 'result' ? 'opacity-100' : 'pointer-events-none opacity-0'
            }`}
            aria-hidden={view !== 'result'}
            {...(view !== 'result' ? { inert: '' } : {})}
          >
            {result && (
              <>
                <div className="mb-4 flex items-start gap-2.5 sm:gap-3">
                  <div
                    className="flex h-11 w-11 sm:h-12 sm:w-12 shrink-0 items-center justify-center rounded-2xl bg-miko-olive/15 dark:bg-miko-olive/20 p-2.5"
                    aria-hidden="true"
                  >
                    <SiteImage
                      imageKey="icon_check"
                      fallback="🎉"
                      alt=""
                      className="w-full h-full object-contain"
                    />
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="mb-1 text-[11px] sm:text-xs font-bold text-miko-olive dark:text-miko-leaf">
                      برآورد اولیه آماده است
                    </p>
                    <h2 className="text-lg font-black leading-tight text-miko-dark dark:text-cream-100 sm:text-2xl">
                      {form.dog_name.trim()}، این نتیجه برای توست!
                    </h2>
                    <p className="mt-1 text-[11px] sm:text-xs leading-5 text-miko-dark/70 dark:text-cream-300">
                      وزن {toFa(weight)} کیلوگرم · سن {totalAgeLabel}
                    </p>
                  </div>
                  <button
                    type="button"
                    onClick={handleEdit}
                    className="shrink-0 rounded-lg border border-miko-carrot/30 px-2.5 sm:px-3 py-2 text-[11px] sm:text-xs font-bold text-miko-olive transition hover:bg-miko-carrot/10 dark:border-dark-600 dark:text-miko-carrot dark:hover:bg-miko-rust/10 min-h-[40px]"
                  >
                    ویرایش
                  </button>
                </div>

                <div className="mb-3 rounded-2xl border border-miko-olive/25 bg-miko-olive/5 p-3">
                  <p className="mb-1 flex items-center gap-1.5 text-sm font-bold text-miko-dark dark:text-cream-200">
                    <SiteImage
                      imageKey="icon_meal"
                      fallback="🍽️"
                      alt=""
                      className="w-4 h-4 object-contain flex-shrink-0"
                    />
                    <span>مقدار پیشنهادی غذا</span>
                  </p>
                  <div className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
                    <span className="text-2xl font-black text-miko-olive dark:text-miko-leaf font-num">
                      {toFa(result.daily?.fresh_weight_g)}
                    </span>
                    <span className="text-sm font-bold text-miko-dark/70 dark:text-cream-300">
                      گرم در روز
                    </span>
                  </div>
                  <p className="mt-1 text-[11px] sm:text-xs text-miko-dark/70 dark:text-cream-300">
                    مجموع غذای روزانه؛ بین وعده‌ها تقسیمش کن.
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-2 sm:gap-3">
                  <ResultCard
                    icon="📦"
                    iconKey="icon_orders"
                    label={`${toFa(result.order_total?.days)} روز غذا`}
                    value={toFaDecimal(result.order_total?.total_weight_kg, 1)}
                    unit="کیلوگرم"
                    featured
                  />
                  <ResultCard
                    icon="💰"
                    iconKey="icon_payment"
                    label="قیمت کل بسته"
                    value={toFa(result.order_total?.total_price_toman)}
                    unit="تومان"
                    featured
                    helper={
                      (result.order_total?.product_price_toman != null ||
                       result.pricing?.order_product_price != null)
                        ? `شامل ارسال ${
                            result.pricing?.shipping_is_free
                              ? 'رایگان'
                              : toFa(result.pricing?.shipping_expense ?? 0) + ' ت'
                          }`
                        : undefined
                    }
                  />
                  {/* ✅ FIX Bug #2: قیمت روزانه ثابت محصول (بدون هزینه ارسال)
                       — در تمام تعداد روزها ثابت می‌ماند.
                       توضیح: result.daily.price_toman شامل هزینه ارسال تقسیم بر روزهاست
                       و با افزایش روز کاهش می‌یافت (گمراه‌کننده).
                       result.daily.product_price_toman فقط هزینه محصول تقسیم بر روزهاست. */}
                  <ResultCard
                    icon="🥣"
                    iconKey="icon_meal"
                    label="هزینه روزانه"
                    value={toFa(
                      result.daily?.product_price_toman ??
                      result.pricing?.daily_product_price ??
                      result.daily?.price_toman ??
                      0
                    )}
                    unit="تومان"
                  />
                  <ResultCard
                    icon="🍴"
                    iconKey="icon_utensils"
                    label="مقدار روزانه"
                    value={toFa(result.daily?.fresh_weight_g)}
                    unit="گرم"
                  />
                </div>

                {/* ✅ FIX Bug #2: توضیح شفاف‌تر — قیمت روزانه شامل هزینه ارسال نیست */}
                <p className="mt-3 text-[11px] sm:text-xs leading-5 text-miko-dark/60 dark:text-cream-400">
                  «هزینه روزانه» شامل هزینه ارسال نیست و در تمام تعداد روزها ثابت می‌ماند.
                  مبلغ نهایی شامل هزینه ارسال است و هنگام ثبت سفارش مشخص می‌شود.
                </p>

                <div className="mt-auto space-y-2 pt-4">
                  <button
                    type="button"
                    onClick={handleReset}
                    className="flex min-h-10 w-full items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-bold text-miko-dark/70 transition hover:bg-miko-carrot/10 dark:text-cream-300 dark:hover:bg-ink-700 touch-target"
                  >
                    <SiteImage
                      imageKey="icon_refresh"
                      fallback="↻"
                      alt=""
                      className="w-4 h-4 object-contain"
                    />
                    <span>محاسبه مجدد</span>
                  </button>
                  <button
                    type="button"
                    onClick={handleContinue}
                    className="group flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-miko-olive px-4 py-3 text-sm font-black text-white shadow-editorial transition hover:brightness-110 dark:bg-miko-leaf touch-target"
                  >
                    <span className="truncate">ادامه و ثبت سفارش</span>
                    <SiteImage
                      imageKey="icon_arrow_left"
                      fallback="←"
                      alt=""
                      className="w-4 h-4 object-contain flex-shrink-0"
                    />
                  </button>
                  <p className="pt-1 text-center text-[11px] sm:text-xs text-miko-dark/60 dark:text-cream-400">
                    هنوز سفارشی ثبت نشده است.
                  </p>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}