// ============================================================
//  ✅ FIX: MOBILE_BREAKPOINT هماهنگ با AdminApp (1280)
//  - زیر 1280px = موبایل/تبلت (نمایش کارت‌محور، گرید کم‌ستونه)
//  - بالای 1280px = دسکتاپ (نمایش جدول کامل)
// ============================================================
const MOBILE_BREAKPOINT = 1280;

// ============================================================
//  🛡️ Helpers
// ============================================================
const getErrorMsg = (err, fallback) => {
  const detail = err?.response?.data?.detail;
  if (typeof detail === 'string') return detail;
  return fallback;
};

const formatDate = (iso) => {
  if (!iso) return '—';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '—';
  return d.toLocaleDateString('fa-IR');
};

// ============================================================
//  🎨 Avatar gradients — Editorial palette
// ============================================================
const AVATAR_GRADIENTS = [
  'from-brand-500 to-brand-700',
  'from-accent-500 to-accent-700',
  'from-rose-500 to-rose-700',
  'from-ink-600 to-ink-800',
  'from-brand-400 to-brand-600',
  'from-accent-400 to-accent-600',
  'from-rose-400 to-rose-600',
  'from-ink-500 to-ink-700',
];

const getAvatarGradient = (id) =>
  AVATAR_GRADIENTS[(Number(id) || 0) % AVATAR_GRADIENTS.length];

// ============================================================
//  🎨 نگاشت وضعیت سفارش — Editorial palette
// ============================================================
