const getOrderStatusCfg = (status) =>
  ORDER_STATUS_CONFIG[status] || {
    label: status || '—',
    icon: '📦', iconKey: 'icon_orders',
    cls: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200 border-ink-200 dark:border-dark-600',
    strip: 'bg-ink-500',
  };

const fmt = (n) => {
  if (n === null || n === undefined || n === '') return '—';
  const num = Number(n);
  if (Number.isNaN(num)) return '—';
  return Math.round(num).toLocaleString('fa-IR');
};

// ============================================================
//  Avatar — Editorial
// ============================================================
function Avatar({ user, size = 'md' }) {
  const initial = (user.full_name || user.username || '?')
    .trim()
    .charAt(0)
    .toUpperCase();
  const gradient = getAvatarGradient(user.id);
  const sizeCls =
    size === 'sm'
      ? 'w-8 h-8 text-xs'
      : size === 'lg'
      ? 'w-12 h-12 text-lg'
      : size === 'xl'
      ? 'w-16 h-16 text-2xl'
      : 'w-10 h-10 text-sm';

  return (
    <div
      className={`${sizeCls} bg-gradient-to-br ${gradient} rounded-full flex items-center justify-center text-white font-black flex-shrink-0 shadow-soft ring-2 ring-paper-50 dark:ring-ink-800`}
    >
      {initial}
    </div>
  );
}

// ============================================================
//  Sort Icon — Editorial
// ============================================================
function SortIcon({ columnKey, sortConfig }) {
  if (sortConfig.key !== columnKey) {
    return (
      <SiteImage imageKey="icon_sort" fallback="↕" alt="" className="text-cream-100/40 text-[10px]" />
    );
  }
  return sortConfig.direction === 'asc' ? (
    <SiteImage imageKey="icon_sort_up" fallback="▲" alt="" className="text-cream-50 text-[10px]" />
  ) : (
    <SiteImage imageKey="icon_sort_down" fallback="▼" alt="" className="text-cream-50 text-[10px]" />
  );
}

